(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c29"]=[{"id":"00004869","register_sub_id":"101","register_pk":"105859","name":"桑原家住宅主屋","kana":"くわはらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県武雄市朝日町大字甘久1956-2","lat":33.21051475,"lng":130.04317817,"geo_status":"db","era":"明治15","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造2階建、瓦葺、建築面積231㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"41 － 0052","desc":"長崎街道に東面して建つ妻入町家。桁行９間梁間５間，切妻造，桟瓦葺の木造２階建で，南側に土間を通し，北側に店・納戸・仏間・座敷などを並べる。階上を塗り込めるが，２階北側客座敷の表側は開放的なつくりとする。棟木墨書から「棟梁橋口徳五郎」が判明。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004869"},{"id":"00002712","register_sub_id":"101","register_pk":"103702","name":"小柳酒造主屋","kana":"こやなぎしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29870579,"lng":130.20287507,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積205㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0027","desc":"街道に東面して建つ。当地方に見られる切妻造，妻入の塗屋造町家で，主体部は桁行７間，梁間４間半とし，南面に１間半幅の下屋を設け，北に８畳座敷を角屋状に張り出す。近年の道路拡幅により正面の下屋を失っているが，小柳酒造の顔となる建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002712"},{"id":"00012256","register_sub_id":"101","register_pk":"353057","name":"齊藤商店店舗兼主屋","kana":"さいとうしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町字蛭子町427","lat":33.293184,"lng":130.200732,"geo_status":"db","era":"昭和2年頃／昭和40年代改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積157㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"41-109","desc":"城下町に建つ近代町家。木造二階建、切妻造平入の出桁造だが、建ちが高くトラス組の大屋根が特徴。一、二階とも四室を配し、欄間彫刻の松竹梅など意匠を凝らす。ガラスを多用し開放的な造りで、ミセの吹抜けやショウウインドウなど洋風意匠も巧みである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012256"},{"id":"00000714","register_sub_id":"101","register_pk":"101704","name":"杉光陶器店一の蔵","kana":"すぎみつとうきてんいちのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県嬉野市塩田町大字馬場下甲728","lat":33.12969191,"lng":130.05996398,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造平屋建，瓦葺，建築面積89㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"41 － 0006","desc":"主屋の後方に位置し，南側の路地に沿って建つ切妻造，２階建の土蔵で，切石積の土台上に建ち外壁に縦板を貼る。かつて敷地の背後は塩田川に直接面し，舟運が盛んであった頃は河川から物資の出入が行われたと伝えるが，往時の様相を知る上でも貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000714"},{"id":"00000716","register_sub_id":"101","register_pk":"101706","name":"杉光陶器店三の蔵","kana":"すぎみつとうきてんさんのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県嬉野市塩田町大字馬場下甲727","lat":33.12981639,"lng":130.05998888,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造平屋建，瓦葺，建築面積69㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"41 － 0008","desc":"主屋の北側に引き込んで建つ切妻造，妻入，２階建の土蔵で，明治末年から一時地元有志の出資により設立された塩田銀行の店舗として使われた。出入口の構えや正面の煉瓦壁は，その時の改造と考えられ，白漆喰塗の町家が連なるなかで特異な外観を呈している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000716"},{"id":"00000713","register_sub_id":"101","register_pk":"101703","name":"杉光陶器店主屋","kana":"すぎみつとうきてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県嬉野市塩田町大字馬場下甲728","lat":33.12985997,"lng":130.059687,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造３階建，瓦葺，建築面積258㎡","structure_material":"木造３階建","registered":"1998.09.02(平成10.09.02)","register_no":"41 － 0005","desc":"塩田川の舟運を用いた物資の集散地として栄えた長崎街道沿の町並みの一画に建つ入母屋造，妻入の土蔵造の大型町家で，正面左手に通り土間，右手に２列の居室を配する構成になる。近年の改装で内部店廻りは一変したが，奥向きの部屋は旧態を良く残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000713"},{"id":"00000715","register_sub_id":"101","register_pk":"101705","name":"杉光陶器店二の蔵","kana":"すぎみつとうきてんにのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県嬉野市塩田町大字馬場下甲727","lat":33.12992843,"lng":130.05974924,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造平屋建，瓦葺，建築面積56㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"41 － 0007","desc":"敷地の東北部に位置し，銀行店舗として使用された三の蔵の背後に棟をそろえて建つ。切妻造，桟瓦葺，２階建の平入土蔵で，出入口に庇が付く。側面及び背面の外壁を縦板貼りとする簡素な造りになる。塩蔵ともよばれ，商家の構えを知る上で貴重な土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000715"},{"id":"00013011","register_sub_id":"101","register_pk":"368084","name":"草伝社（旧井手家住宅）倉庫","kana":"そうでんしゃ（きゅういでけじゅうたく） そうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県唐津市北波多徳須恵字前田1030-3他","lat":33.37580278,"lng":129.95135833,"geo_status":"db","era":"明治後期／昭和前期・平成21年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積47㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"41 － 112","desc":"店舗兼主屋北側に並んで建つ。木造二階建、切妻造桟瓦葺、外壁縦板張で、南面中央に戸口を設け、西妻を路地に面する。当初は二階を渡廊下で店舗兼主屋に接続し、一体の収納空間として利用した。唐津周辺の商家の伝統的な店構えを伝える附属建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013011"},{"id":"00013010","register_sub_id":"101","register_pk":"368083","name":"草伝社（旧井手家住宅）店舗兼主屋","kana":"そうでんしゃ（きゅういでけじゅうたく） てんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県唐津市北波多徳須恵字前田1030-3他","lat":33.37566667,"lng":129.95129167,"geo_status":"db","era":"明治後期／大正後期・昭和中期・平成24年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積241㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"41 － 111","desc":"市東部旧徳須恵宿のもと商家。店舗兼主屋は路地に西面して建つ切妻造桟瓦葺の二階建で、北に土間、南に二列四室を配して南列奥を客座敷とし、北の落棟に台所等、南の別棟に続き間の座敷を設ける。二階は一空間の倉庫とする。宿場町の景観を伝える大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013010"},{"id":"00000608","register_sub_id":"101","register_pk":"101598","name":"竹屋","kana":"たけや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県唐津市中町1884-2","lat":33.44856014,"lng":129.97036131,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造３階建，瓦葺，建築面積100㎡","structure_material":"木造３階建","registered":"1998.07.23(平成10.07.23)","register_no":"41 － 0004","desc":"唐津市の繁華街にある老舗の料理店竹屋の木造３階建の店舗。１階は調理場と家族の住居部であるが，２階は６畳代の客室が３室，３階は１０畳代の客室が２室が配される。いずれも吟味された材料を用い，階段廻りや客室の欄間，床棚など凝った造作になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000608"},{"id":"00013669","register_sub_id":"101","register_pk":"504613","name":"永井家住宅店舗兼主屋","kana":"ながいけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県唐津市呼子町呼子字坊山3085","lat":33.54025278,"lng":129.89503333,"geo_status":"db","era":"江戸後期／昭和前期増築、同中期・平成8年・同19年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積194㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"41 － 0113","desc":"呼子湾沿いの道に東面して建つ二階建、切妻造平入、桟瓦葺の町家。間口六間半で、正面に持送付の腕木庇を付し、二階外壁を漆喰塗とする。北を床上部、南を通り土間とし、通り土間西半の吹抜に貫を多用した小屋組を現す。港町呼子で江戸後期に遡る貴重な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013669"},{"id":"00005681","register_sub_id":"101","register_pk":"106669","name":"中島酒造場主屋","kana":"なかしましゅぞうじょうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2714他","lat":33.092297,"lng":130.115097,"geo_status":"db","era":"明治18","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造2階建、瓦葺、建築面積513㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0065","desc":"旧長崎街道多良往還に北面して建つ。木造２階建の塗家造で，入母屋造，桟瓦葺，妻入の店舗を中心に，西側に玄関・２階建の離座敷・土蔵が，東側に東西棟の倉庫が，主棟土間の背後には釜場が接続する。店舗の２階正面は木格子窓とし，両脇に漆喰塗の戸袋がつく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005681"},{"id":"00001538","register_sub_id":"101","register_pk":"102528","name":"野中烏犀圓","kana":"のなかうさいえん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"佐賀県","address":"佐賀県佐賀市材木1-82","lat":33.25341793,"lng":130.30979424,"geo_status":"db","era":"寛政8／昭和3増築","year":1796,"year_source":"db","year_min":1796,"year_max":1796,"year_label":null,"structure":"木造2階建、瓦葺、建築面積363㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"41 － 0014","desc":"野中烏犀圓は寛永３年創業と伝わる老舗薬問屋。冷善楼と呼ばれる座敷と店以外は増築部分。広く街路に面する漆喰壁，正面中央の大破風，看板を吊す屋形が江戸期の商家の風情を伝え，長崎街道周辺の歴史的景観形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001538"},{"id":"00004471","register_sub_id":"101","register_pk":"105461","name":"肥前浜宿継場主屋","kana":"ひぜんはましゅくつぎばしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2696","lat":33.09250271,"lng":130.11460976,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積126㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"41 － 0048","desc":"旧長崎街道多良往還沿いに建つもと継立場。往還に南妻面を見せた間口４間半の妻入商家で，１階の表構えは揚戸の形式とし，２階は小庇付きの窓２箇所を開ける。内部は東側を土間に充て，西側にミセ，チャノマ，ザシキを一列に並べ，土間奥をカマヤとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004471"},{"id":"00010073","register_sub_id":"101","register_pk":"196220","name":"町家カフェぜん","kana":"まちやかふぇぜん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県唐津市坊主町552-5","lat":33.45139085,"lng":129.96464058,"geo_status":"db","era":"大正14／昭和10・平成24改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積163㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"41 － 0094","desc":"唐津城下の西方に位置し、通りに東面して建つ。もとは南半を質屋の店舗、北半を住宅として使用した。二階南半は質倉で、防火防犯に考慮して開口部を小さくし、外観もモルタル塗込めとして、銅板で建具や桁木口等を覆う。当時の質店の建築的特徴をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010073"},{"id":"00005669","register_sub_id":"101","register_pk":"106657","name":"矢野酒造主屋","kana":"やのしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市大字高津原字一本杉3903-1他","lat":33.11300079,"lng":130.0937829,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、瓦葺、建築面積284㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0053","desc":"旧長崎街道多良往還に東面して建つ，間口６間の木造２階建で，入母屋造，桟瓦葺の妻入とする。正面１階は瓦葺庇の南寄りに戸口を設け，北側を出窓とし，２階外壁は白漆喰塗である。内部は南側に通り土間，北側の表を土間の事務室とし，２列４室の居室を配す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005669"},{"id":"00007599","register_sub_id":"101","register_pk":"108581","name":"吉田家住宅主屋","kana":"よしだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市大字中村字本町103","lat":33.11614921,"lng":130.09521428,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積228㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"41 － 0071","desc":"多良海道に西面する木造２階建の町家。入母屋造桟瓦葺で、背面直角に入母屋造を出す。外壁を白漆喰仕上げの大壁とし、側面は腰に煉瓦を積む。内部は南側の通り土間、北側の居室からなり、座敷には黒檀ほかの銘木を使う。居蔵造の形態をよく伝える近代町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007599"},{"id":"00007600","register_sub_id":"101","register_pk":"108582","name":"吉田家住宅土蔵","kana":"よしだけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市大字中村字本町103","lat":33.11608673,"lng":130.09529475,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"41 － 0072","desc":"敷地の後方に東西棟で建つ。土蔵造２階建で、切妻造妻入桟瓦葺とする。外壁は漆喰仕上げ。内部は１階を広い１室とし、２階を３室に間仕切り、西に納戸を配し、中央の四畳から東端の十畳にかけて舟底天井を張り、室境に欄間を設ける。町家に残る座蔵の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007600"},{"id":"00003484","register_sub_id":"101","register_pk":"104474","name":"青い理髪舘（旧小林理髪舘）","kana":"あおいりはつかん（きゅうこばやしりはつかん）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県島原市上の町888-2","lat":32.79155707,"lng":130.36813472,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積60㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"42 － 0025","desc":"上の町北端で島原街道から西に折れる道路に北面して建つ。間口３間，寄棟造，桟瓦葺の木造，下見板張，２階建洋館。花頭窓風のアーチとキーストーンをあしらった玄関上部のペディメント風意匠は特異で，３連の造り付け鏡面台など理髪室内部の保存状況も良い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003484"},{"id":"00003490","register_sub_id":"101","register_pk":"104480","name":"猪原金物店主屋","kana":"いのはらかなものてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県島原市上の町912","lat":32.78889187,"lng":130.36939063,"geo_status":"db","era":"万延2及び明治後期","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"42 － 0031","desc":"島原街道の西側に位置する。万延２年の棟札を持つ切妻造・平入の北側上手部分と，明治後期の切妻造・平入の南側下手部分とが一体となり，正面東面と南面に半間の下屋を廻す。商店街の入口近くに在り，上の町の「顔」的存在として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003490"},{"id":"00005382","register_sub_id":"101","register_pk":"106370","name":"今里酒造店舗及び住宅","kana":"いまざとしゅぞうてんぽおよびじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県東彼杵郡波佐見町宿郷596","lat":33.13629835,"lng":129.89660384,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積442㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"42 － 0050","desc":"川棚川右岸沿いの敷地に位置し，上波佐見村往還に南面して建つ。東西棟，入母屋造，平入のつし２階建の背後に南北棟の切妻造を続け，南妻の一部を往還に見せる独特なつくり。ほぼ中央に南北に土間を通し豪壮な梁組を見せ，西方を事務所，東方を床上部とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005382"},{"id":"00002727","register_sub_id":"101","register_pk":"103717","name":"梅ヶ枝酒造主屋","kana":"うめがえしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県佐世保市城間町317","lat":33.089905,"lng":129.814941,"geo_status":"db","era":"安政7","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積216㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"42 － 0012","desc":"宮村川右岸，平戸往還近くに位置する敷地のほぼ中央に建つ。桁行１８ｍ，梁間８ｍ規模，東西棟，片入母屋造，桟瓦葺の主体部の南に４ｍ幅の下屋を架けて東寄りに玄関をとる。造り酒屋の住居兼事務所で，土間部を中心に試飲所や販売所としても活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002727"},{"id":"00003171","register_sub_id":"101","register_pk":"104161","name":"雲仙観光ホテル","kana":"うんぜんかんこうほてる","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県雲仙市小浜町雲仙湯ノ里320","lat":32.737297,"lng":130.26152,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造一部鉄筋コンクリート造地上3階地下1階建、瓦葺、建築面積1772㎡","structure_material":"木造一部鉄筋コンクリート造地上3階地下1階建","registered":"2003.01.31(平成15.01.31)","register_no":"42 － 0019","desc":"正面約６５ｍ規模，地下１階地上３階建で北面して建つ。外観はアルプス山小屋風を基調に，１階は溶岩石張，２階はログハウス風，３階はハーフティンバー風の構成とし，内部も木質感を活かした重厚で格調高いインテリア空間をつくる。竹中工務店の設計施工。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003171"},{"id":"00006628","register_sub_id":"101","register_pk":"107611","name":"小野原本店店舗兼主屋","kana":"おのはらほんてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県長崎市築町3-5","lat":32.74521056,"lng":129.87585749,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積84㎡、地下室付","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"42 － 0072","desc":"角地に建ち、東側通りに正面を向ける。入母屋造妻入桟瓦葺、隅切りのある桁行４間梁間４間半の２階建で、北に突出部を設ける。２階を黒漆喰壁とし、両開鉄扉を正・側面に計１０ヶ所開ける。１階に店舗、２階に座敷を設ける。重厚な意匠になる商家建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006628"},{"id":"00006629","register_sub_id":"101","register_pk":"107612","name":"小野原本店附属屋","kana":"おのはらほんてんふぞくや","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県長崎市築町3-5","lat":32.74530566,"lng":129.87593331,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"煉瓦造2階建、建築面積41㎡","structure_material":"煉瓦造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"42 － 0073","desc":"主屋の北側に正面壁面を合わせて建つ。煉瓦造２階建で、パラペットを立ちあげ、モルタル塗仕上げとする。当初は１階が食堂、２階が納戸で、主屋突出部を介して主屋と一連で使われた。黒漆喰仕上げの主屋と対照的な外観や構造をもち、独特の街路景観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006629"},{"id":"00016615","register_sub_id":"101","register_pk":"574977","name":"旧親和銀行本店懐霄館","kana":"きゅうしんわぎんこうほんてんかいしょうかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和後","pref":"長崎県","address":"長崎県佐世保市島瀬町80他","lat":33.17199389,"lng":129.72233583,"geo_status":"db","era":"昭和50年","year":1975,"year_source":"db","year_min":1975,"year_max":1975,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上11階地下2階建、建築面積789㎡、渡廊下付","structure_material":"鉄骨鉄筋コンクリート造地上11階地下2階建","registered":"2026.02.10(令和8.02.10)","register_no":"42 - 0148","desc":"本館背面に屹立する旧電算機棟。正面は花崗岩貼で中央の長大なスリットに向かい壁面が湾曲する独特の造形。巨大な吹抜や業務室に、展望室、噴水付サロン、ギャラリーなどの異質空間を巧みに配する。本館と一体で白井晟一の世界観を完成させた記念碑的作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016615"},{"id":"00016614","register_sub_id":"101","register_pk":"574976","name":"旧親和銀行本店本館","kana":"きゅうしんわぎんこうほんてんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和後","pref":"長崎県","address":"長崎県佐世保市島瀬町80他","lat":33.17199389,"lng":129.72233583,"geo_status":"db","era":"昭和42年／昭和44増築、平成16年・令和4年改修","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造地上6階地下1階建、建築面積1，792㎡","structure_material":"鉄筋コンクリート造一部鉄骨造地上6階地下1階建","registered":"2026.02.10(令和8.02.10)","register_no":"42 - 0147","desc":"佐世保駅から北西に延びる商店街に東面する銀行店舗。「原爆堂計画」の造形を原型とする北半部と、ブロンズパネル貼の弓形構造体を立上げた南半部からなる独創的外観。円筒内壁を巡る螺旋階段など彫塑的な造形が静謐な空間を創出。白井晟一の代表作の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016614"},{"id":"00011012","register_sub_id":"101","register_pk":"208982","name":"旧角屋主屋","kana":"きゅうすみやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県平戸市田助町字浦方68","lat":33.39034,"lng":129.55375,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積228㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"42-0124","desc":"田助湾に面する敷地に西面する。Ｌ字形平面の木造二階建、入母屋造桟瓦葺で下屋を廻らし、正面中央に入母屋玄関を構える。正面と海側の背面は広い開口にガラス戸をたてる。一階東寄りを土間とする他は上下階とも中廊下沿いに居室を配し、造作も洗練される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011012"},{"id":"00011224","register_sub_id":"101","register_pk":"205331","name":"旧升金商会事務所兼倉庫","kana":"きゅうますきんしょうかいじむしょけんそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市湊新地町450-1","lat":32.774237,"lng":130.375582,"geo_status":"db","era":"明治10頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造2階建、瓦葺、建築面積133㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"42 - 0128","desc":"店舗兼主屋の街路を隔てた南側に立ち、背面側は海に面する。桁行八間弱、梁間四間半の蔵で、木造二階建、切妻造桟瓦葺。一尺五寸角の柱・梁材など、木太い材を用いる点が特徴で、高い大工技術によって組まれている。港町島原の繁栄の様相を物語る建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011224"},{"id":"00011223","register_sub_id":"101","register_pk":"205330","name":"旧升金商会店舗兼主屋","kana":"きゅうますきんしょうかいてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市湊新地町420","lat":32.774388,"lng":130.375378,"geo_status":"db","era":"明治15","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造2階建、瓦葺、建築面積163㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"42 - 0127","desc":"明治三年に島原藩によって開かれた湊新地の角地に建つ。南北棟の南寄り西側に東西棟を張り出す鉤手状の平面を持ち、隅部に大きくミセを配す。主屋主体部の上手表側に仏間を配する平面は、江戸末期から明治期にかけての島原に多く見られる形式。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011223"},{"id":"00007937","register_sub_id":"101","register_pk":"108917","name":"旧松本薬局店舗兼主屋","kana":"きゅうまつもとやっきょくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県壱岐市勝本町勝本浦字本浦158-3","lat":33.85065787,"lng":129.69411332,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積210㎡","structure_material":"木造2階一部平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"42-0087","desc":"通りに南面して建つ。東西敷地境に高い煉瓦塀を造り、建物側壁とし、店舗と座敷を庭を介して一体とする。正面は煉瓦塀をウダツ風に飾り、１階に出格子を構え、庇を腕木で持ち出す。２階はモルタル壁を石貼風に目地を切る。多様な要素が調和する町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007937"},{"id":"00013671","register_sub_id":"101","register_pk":"505030","name":"銀水","kana":"ぎんすい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県島原市白土桃山二丁目1093","lat":32.77885833,"lng":130.37472778,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積56㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"42 － 0137","desc":"島原城の南方、浜の川湧水の東に北面して建つ名物冷菓かんざらしの店舗。木造二階建、桟瓦葺、一階東半を土間とし、玄関正面の水溜に湧水を引いてミセとする。西半は床付の和室で仏壇を備え、二階は瀟洒な座敷二室を設ける。湧水の歴史的風致を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013671"},{"id":"00016616","register_sub_id":"101","register_pk":"574978","name":"ＳＥＥＤ１９３１（旧諫早銀行本店）","kana":"しーどいちきゅうさんいち（きゅういさはやぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県諫早市本町108-1","lat":32.84517472,"lng":130.05480694,"geo_status":"db","era":"昭和6年／令和6年改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造2階建、塔屋付、建築面積308㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"42 - 0149","desc":"市街地中心部の本町通りの角地に建つ、旧銀行本店店舗。鉄筋コンクリート造2階建、ドリス式オーダーの列柱や軒飾による重厚な意匠で、内部は旧営業室を有し、吹抜の大空間にトスカナ式オーダーの円柱を立てる。古典様式の外観が街角景観をつくる銀行建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016616"},{"id":"00003335","register_sub_id":"101","register_pk":"104325","name":"中尾山うつわ処赤井倉","kana":"なかおやまうつわどころあかいぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県東彼杵郡波佐見町中尾郷929","lat":33.12261841,"lng":129.92900389,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積168㎡","structure_material":"木造平屋一部2階建","registered":"2003.03.18(平成15.03.18)","register_no":"42 － 0021","desc":"中尾郷を南北に流れる中尾川右岸沿い敷地にほぼ西面して建つ。桁行８間梁間２間半規模の入母屋造身舎部の西と南面に幅５尺の広縁を廻し，東面には梁行１間半の下屋を差出す。北をドマ，中央をミセ，南をザシキとした商家建築の好事例。棟梁は小玉政治。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003335"},{"id":"00003488","register_sub_id":"101","register_pk":"104478","name":"中野金物店主屋","kana":"なかのかなものてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県島原市上の町906","lat":32.78938473,"lng":130.36918449,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、建築面積63㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"42 － 0029","desc":"島原街道の西側に位置し，東面して建つ。間口３間梁間５間規模，南北棟の切妻造，桟瓦葺，平入のたちの高い本２階建で，正面に１間の下屋を付ける。北側が切り縮められているが，つし２階建から本２階建町家への移行を示す指標的遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003488"},{"id":"00003489","register_sub_id":"101","register_pk":"104479","name":"中野金物店防火壁","kana":"なかのかなものてんぼうかへき","category":"産業3次","subcategory":"その他工作物","type_guess":"店舗","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県島原市上の町906","lat":32.78932798,"lng":130.36910499,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"煉瓦造、延長13m","structure_material":"煉瓦造","registered":"2003.07.01(平成15.07.01)","register_no":"42 － 0030","desc":"南側隣地との境界に建ち，主屋の南妻面を構成する。煉瓦造で，２枚厚の根積に１枚半厚の防火壁をイギリス積で建ちあげる。主屋２階部は袖卯建状とし，笠石部は煉瓦で小屋根を造り，南妻破風は３段の持出し積とするなど凝った造作が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003489"},{"id":"00003485","register_sub_id":"101","register_pk":"104475","name":"宮崎商店店舗","kana":"みやざきしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市上の町897","lat":32.79037414,"lng":130.36877659,"geo_status":"db","era":"明治39／昭和6増改造","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建、瓦葺、建築面積70㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"42 － 0026","desc":"島原街道の西側に位置し，南側に城に向う小路が通る角地に建つ。造り酒屋の店舗棟と座敷棟から成り，店舗棟は南北棟で，桁行４間半規模，切妻造，桟瓦葺の平入とし，北に東西棟，入母屋造のたちの高い座敷棟をＬ型に配する。店舗棟の棟梁は「荒木輝美雄」。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003485"},{"id":"00013471","register_sub_id":"101","register_pk":"368567","name":"旧岩﨑家住宅（塩屋）店舗兼主屋","kana":"きゅういわさきけじゅうたく（しおや）てんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県宇城市小川町小川字上苅萱79-1","lat":32.58510556,"lng":130.70732778,"geo_status":"db","era":"明治39年／昭和40年頃・平成12年・同30年改修","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建、瓦葺、建築面積211㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"43 － 0180","desc":"旧薩摩街道小川宿に位置し、街道に北面して建つ。木造二階建、切妻造桟瓦葺平入、外壁は白漆喰塗で、妻面に水切瓦を三段廻らす。内部は東を土間、西を座敷とし、主座敷に床、棚、書院を備える。正面外観は改修しているが、建築年代が明らかで上質な町家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013471"},{"id":"00009683","register_sub_id":"101","register_pk":"194679","name":"旧松倉家住宅主屋","kana":"きゅうまつくらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県菊池市隈府字城山1329-2","lat":32.98529372,"lng":130.81154373,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積148㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"43 － 0123","desc":"御所通りに面して建ち、木造二階建、入母屋造桟瓦葺で、通り側に大小の入母屋屋根を見せ、一階は出格子をたて、二階は窓を広く取り手摺を設ける。当初は料理屋として建てられたため、座敷飾や欄間などを瀟洒つくりとし、接客建築らしい意匠を随所に見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009683"},{"id":"00004479","register_sub_id":"101","register_pk":"105469","name":"旧三角海運倉庫（三角築港記念館）","kana":"きゅうみすみかいうんそうこ（みすみちくこうきねんかん）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県宇城市三角町三角浦1268-1","lat":32.62228,"lng":130.455505,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積168㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"43 － 0074","desc":"三角旧港東南の埠頭沿いに位置する旧海運倉庫。桁行２５ｍ梁間７ｍ規模の土蔵造２階建，平入で，埠頭側に下屋庇を２間張り出し，その他の３面には水切り瓦を付ける。築港当初に建てられた倉庫としては唯一の遺構で，現在レストランとして活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004479"},{"id":"00014985","register_sub_id":"101","register_pk":"519245","name":"商工クラブ店舗","kana":"しょうこうくらぶてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市中央区西阿弥陀寺町6","lat":32.79405833,"lng":130.69517778,"geo_status":"db","era":"明治23年／令和2年改修","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造2階建、瓦葺、建築面積266㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"43 - 0201","desc":"熊本城跡の南西の市街地に位置する料亭。通りに北面する２階建切妻造平入桟瓦葺の東西棟で、南東に角屋を延ばす。一階は出格子と平格子構えで東寄りに入母屋造玄関を付し、二階は連窓前面に手擦を廻らし窓上に庇を付す。近代の熊本城下の賑わいを伝える料亭。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014985"},{"id":"00005513","register_sub_id":"101","register_pk":"106501","name":"冨重写真所","kana":"とみしげしゃしんじょ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市新町2-8-5","lat":32.79747553,"lng":130.69943807,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積138㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"43 － 0078","desc":"西側接道の敷地の南東に西面して建つ。桁行７間，梁間３間規模で，東西棟，切妻造，桟瓦葺の木造２階建。外壁は下見板張とする。坪井川に面する東側には，１階に手摺付の縁を設け，庇を張り出す。スラントを用いた撮影室を残す，明治期の写真館の遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005513"},{"id":"00000491","register_sub_id":"101","register_pk":"101481","name":"長崎次郎書店","kana":"ながさきじろうしょてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"大正","pref":"熊本県","address":"熊本県熊本市新町4-1-19","lat":32.80030968,"lng":130.69671848,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建，瓦葺，建築面積175㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"43 － 0006","desc":"旧城下の商人町の中心近くに建つ。木造２階建で，外壁は煉瓦で固める。設計は保岡勝也。軒の出の小さい屋根，障壁風の壁の上部に設けた小屋根，軒廻りの装飾，２階の連続する変形のアーチ等に特徴がある。市内有数の古い書店として広く知られた建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000491"},{"id":"00013470","register_sub_id":"101","register_pk":"368566","name":"西村家住宅主屋","kana":"にしむらけじゅうたくおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県熊本市中央区西唐人町13","lat":32.79766389,"lng":130.6971,"geo_status":"db","era":"大正6年頃／平成5年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積146㎡、煉瓦造防火壁付","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"43 － 0179","desc":"店舗背面に続く、商家の主屋。木造二階建桟瓦葺で、店舗西側の路地が玄関へ続く。玄関の北に茶の間、西に水回り、東に座敷を配し、南の縁から仏間に接続する。黒檀や桜の面皮柱などの多様な材、工夫を凝らした明り窓など、賓客をもてなす設えを随所に見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013470"},{"id":"00013469","register_sub_id":"101","register_pk":"368565","name":"西村家住宅店舗","kana":"にしむらけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県熊本市中央区西唐人町10","lat":32.79748889,"lng":130.69702222,"geo_status":"db","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積105㎡","structure_material":"土蔵造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"43 － 0178","desc":"熊本城下の西唐人町に位置し、通りに南面して建つ。土蔵造二階建、切妻造桟瓦葺平入で、正面半間、背面一間半の下屋を付し、外壁を黒漆喰塗とし、東妻面は煉瓦造防火壁と一体化する。一、二階とも一室で、小屋を現しとする。近代熊本の繁華街の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013469"},{"id":"00006503","register_sub_id":"101","register_pk":"107486","name":"浜田醤油店舗","kana":"はまだしょうゆてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県熊本市小島中町107","lat":32.777149,"lng":130.635956,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"43 － 0093","desc":"通り沿いに東面して建つ、桁行６間、梁間５間、切妻造桟瓦葺の平入木造２階建。外観を塗り込め、南半には深い下屋庇をつくり、開口を設け、北半は腰を海鼠壁とするなど意匠を違える。老舗に相応しい、重厚で風格ある表情をみせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006503"},{"id":"00006463","register_sub_id":"101","register_pk":"107446","name":"浜田醤油洋館","kana":"はまだしょうゆようかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"熊本県","address":"熊本県熊本市小島中町107","lat":32.777031,"lng":130.63599242,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積8㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"43 － 0095","desc":"敷地東南角に建ち、主屋に接続する。建築面積８㎡、木造２階建、桟瓦葺。もと煙草店として建てられ、現在は１階を倉庫、２階を居室とする。外壁はモルタル塗で、２階の腰から下を洗出し仕上げとする。妻壁は山型で板張の妻飾をつけて洋風意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006463"},{"id":"00000108","register_sub_id":"101","register_pk":"101098","name":"早野ビル","kana":"はやのびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県熊本市練兵町45","lat":32.79788395,"lng":130.7027671,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造3階建（一部4階建）、建築面積208㎡","structure_material":"鉄筋コンクリート造3階建（一部4階建）","registered":"1996.12.20(平成8.12.20)","register_no":"43 － 0001","desc":"ＲＣ造の事務所ビルで，設計は矢上信次である。熊本で最初の貸しビルであったと伝えており，２・３階を通した窓廻り，４階及び塔屋の窓廻り，外壁の柱型等に特徴的な装飾が施されている点に初期の事務所ビルの特徴がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000108"},{"id":"00000808","register_sub_id":"101","register_pk":"101798","name":"ピーエス熊本センター（旧第一銀行熊本支店）","kana":"ぴーえすくまもとせんたー（きゅうだいいちぎんこうくまもとしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県熊本市中唐人町1","lat":32.7969975,"lng":130.69867187,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造地上２階地下１階建，建築面積332㎡","structure_material":"鉄筋コンクリート造地上２階地下１階建","registered":"1998.09.02(平成10.09.02)","register_no":"43 － 0013","desc":"西村好時の設計。全国の第一銀行の設計を手がけた西村の初期の作として知られる。連続するアーチ窓を用い，道路側の両端に塔屋を配し，石と煉瓦で仕上げた外観は美しく，地域のランドマークにもなっている。内部には１・２階吹き抜けの営業室をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000808"},{"id":"00003927","register_sub_id":"101","register_pk":"104917","name":"氷川町まちつくり酒屋（旧井芹家住宅）主屋","kana":"ひかわちょうまちつくりさかや（きゅういせりけじゅうたく）おもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県八代郡氷川町宮原栄久31-15","lat":32.55617379,"lng":130.68218257,"geo_status":"db","era":"天保3／明治6増築","year":1832,"year_source":"db","year_min":1832,"year_max":1832,"year_label":null,"structure":"木造2階建、瓦葺、建築面積281㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"43 － 0067","desc":"旧井芹銀行本店の北側に位置する。切妻造，平入で，街路に面する正面の２階は漆喰で塗り込めるが，背面は１，２階とも縁側を張り出した開放的な外観とする。大きな妻面に水切瓦と瓦葺庇付の開口部が穿たれる。大規模なつくりで地域のランドマークとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003927"},{"id":"00003928","register_sub_id":"101","register_pk":"104918","name":"氷川町まちつくり酒屋（旧井芹家住宅）土蔵","kana":"ひかわちょうまちつくりさかや（きゅういせりけじゅうたく）どぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県八代郡氷川町宮原栄久31-15","lat":32.55613644,"lng":130.68183425,"geo_status":"db","era":"明治5／平成12移築","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"43 － 0068","desc":"旧井芹銀行本店の背面に位置する旧米蔵。桁行４間，梁間２間の，切妻造，桟瓦葺，平入で，基礎に切石を敷いた２階建の土蔵。小屋組は和小屋で，平側全面には幅１間で角状の下屋柱を三本張り出す。醸造業を経営していた頃の屋敷の構成要素として貴重な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003928"},{"id":"00003926","register_sub_id":"101","register_pk":"104916","name":"氷川町まちづくり情報銀行（旧井芹銀行本店）","kana":"ひかわちょうまちづくりじょうほうぎんこう（きゅういせりぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県八代郡氷川町宮原栄久35-1","lat":32.55598146,"lng":130.68209296,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積106㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"43 － 0066","desc":"町の中心地で，町役場に近接して建つ銀行建築。左右対称の外観を呈する鉄筋コンクリート造２階建で，正面に特異な意匠の柱頭付の付柱を四本設け，パラペット中央部に幾何学的模様を施すなど，全体をセセッション風の意匠でまとめる。施工は地元の増永組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003926"},{"id":"00009561","register_sub_id":"101","register_pk":"194354","name":"人吉旅館玄関棟","kana":"ひとよしりょかんげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県人吉市上青井町154-1","lat":32.21209548,"lng":130.75417863,"geo_status":"db","era":"昭和8年／昭和12年・昭和14年増築・昭和63年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積407㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"43 － 0114","desc":"敷地北西に建つ。木造二階建、建築面積四〇七平方メートル、入母屋造桟瓦葺で、正面に入母屋造の玄関を構える。下階に玄関ホールや応接間、上階に大ホールや客室を配し、上下階とも東面の中庭側にガラス戸を建てて開放的につくる。風情ある和風旅館の玄関棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009561"},{"id":"00009563","register_sub_id":"101","register_pk":"194356","name":"人吉旅館中央棟","kana":"ひとよしりょかんちゅうおうとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県人吉市上青井町154-1","lat":32.21198698,"lng":130.75431141,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積234㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"43 － 0116","desc":"敷地の南辺中央、東棟と西棟の間に建つ。木造二階建、建築面積二三四平方メートル、入母屋造桟瓦葺である。上下階とも四室を一列に並べ、各々違棚や組子欄間の意匠を違える。北面に廊下を通し、各室の南に縁を配して球磨川を望む。河岸景観に趣を添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009563"},{"id":"00009564","register_sub_id":"101","register_pk":"194357","name":"人吉旅館西棟","kana":"ひとよしりょかんにしとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"熊本県","address":"熊本県人吉市上青井町154-1","lat":32.21194986,"lng":130.7542286,"geo_status":"db","era":"昭和28年／昭和57年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積139㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"43 － 0117","desc":"玄関棟と中央棟の接点に建つ客室棟。木造二階建、建築面積一三九平方メートル、切妻造桟瓦葺。上下階とも球磨川に面して三室ずつを並べる。摺ガラスの回転窓や矢岳の透彫欄間を建てるほか、竹や自然木を用いて数寄屋風を加味するなど細部に趣向を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009564"},{"id":"00009562","register_sub_id":"101","register_pk":"194355","name":"人吉旅館東棟","kana":"ひとよしりょかんひがしとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県人吉市上青井町154-1","lat":32.2120398,"lng":130.75441991,"geo_status":"db","era":"昭和5年頃／昭和40年・昭和52年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積94㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"43 － 0115","desc":"敷地南東に建ち、木造二階建、建築面積九四平方メートル、入母屋造桟瓦葺である。室内は、下階に客室富士・扇の二室、上階に清流の間を配する。トコに扇形の墨跡窓を開け、随所に銘木を用いて、各室とも瀟洒な意匠とする。創業頃の敷地の様相を伝える客室棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009562"},{"id":"00002864","register_sub_id":"101","register_pk":"103854","name":"山鹿灯籠民芸館（旧安田銀行山鹿支店）","kana":"やまがとうろうみんげいかん（きゅうやすだぎんこうやまがしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県山鹿市大字山鹿1606-2","lat":33.01514407,"lng":130.68842465,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積185㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"43 － 0049","desc":"山鹿市街中心部に建つ銀行社屋。ＲＣ造２階建で，内部はその大部分を営業室とし，西側に事務室等を設ける。外観はイオニア式風のオーダーを用いて様式主義でまとめるが，角形のスクロールや，玄関上部のパラペット装飾など細部に特色が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002864"},{"id":"00009567","register_sub_id":"101","register_pk":"194360","name":"芳野旅館居間棟","kana":"よしのりょかんいまとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県人吉市上青井町184-1他","lat":32.21422986,"lng":130.756323,"geo_status":"db","era":"明治21年／昭和46年改修","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積110㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"43 － 0120","desc":"別広間棟の西側に接続する。木造平屋建、建築面積一一〇平方メートル、入母屋造及び切妻造桟瓦葺である。内部は居間四室と仏間などにより構成される。創業者の住居を存置し利用している、敷地内最古の建物で、住宅から温泉旅館へと変遷した経緯を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009567"},{"id":"00009568","register_sub_id":"101","register_pk":"194361","name":"芳野旅館従業員棟","kana":"よしのりょかんじゅうぎょういんとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県人吉市上青井町184-1他","lat":32.21439404,"lng":130.75623306,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積171㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"43 － 0121","desc":"本館西側に建ち、木造二階建、建築面積一七一平方メートル、入母屋造桟瓦葺である。銭湯として建てられたのち料亭を経て従業員室や倉庫となる。室ごとに異なる意匠の下地窓を穿ち、二階張出し部に色ガラスを配した窓を建てるなど、洗練された雰囲気をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009568"},{"id":"00009566","register_sub_id":"101","register_pk":"194359","name":"芳野旅館別広間棟","kana":"よしのりょかんべつひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県人吉市上青井町184-1他","lat":32.21422986,"lng":130.75651288,"geo_status":"db","era":"大正2年／昭和中期・昭和46年増築","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積290㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"43 － 0119","desc":"本館南側に接続し、木造二階建、入母屋造桟瓦葺である。下階は、廊下の北側に別広間、南側に厨房や休憩室などを配し、上階は客室とする。廊下を竹垂木の舟底天井とし、客室には目の細かい網代天井を張るなど、竹や自然木を巧みに用いて趣ある座敷空間とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009566"},{"id":"00009565","register_sub_id":"101","register_pk":"194358","name":"芳野旅館本館","kana":"よしのりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県人吉市上青井町184-1他","lat":32.21448399,"lng":130.75650051,"geo_status":"db","era":"昭和6年／昭和11年増築・昭和50年改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積454㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"43 － 0118","desc":"山田川西岸の敷地北寄りに建つ。木造二階建、建築面積四五四平方メートル、入母屋造桟瓦葺で、北面に入母屋造の玄関を構える。下階を玄関ホールと客室、上階に大広間を配する。内部造作に、舟運に因む舟板や水車の古材を転用するなど風情あるつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009565"},{"id":"00007703","register_sub_id":"101","register_pk":"108685","name":"旅館金波楼大広間棟","kana":"りょかんきんぱろうおおひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県八代市日奈久上西町字西町又361他","lat":32.43261783,"lng":130.57389496,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積356㎡、煙突付","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"43 － 0106","desc":"本館に接続して南北棟で建ち、北西隅には高さ１５ｍの煉瓦造の煙突を付ける。大規模な木造２階建で、入母屋造桟瓦葺とし、東から南にかけて下屋庇をまわす。２階の八十畳の大広間は網代組の舟底天井で、トコや違棚、琵琶トコには自然木の銘木を大胆にあしらう。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007703"},{"id":"00007704","register_sub_id":"101","register_pk":"108686","name":"旅館金波楼正門及び塀","kana":"りょかんきんぱろうせいもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県八代市日奈久上西町字西町又361他","lat":32.43301853,"lng":130.57402849,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 木造、瓦葺、間口2.3m、左右袖塀付、塀 木造、瓦葺、総延長26m","structure_material":"門 木造","registered":"2009.04.28(平成21.04.28)","register_no":"43 － 0107","desc":"通りに面して建つ一間腕木門。切妻造桟瓦葺で、緩い起りを付ける。間口２．３ｍで、両開板戸をたて、上部に筬欄間を飾る。西袖塀に潜りを設け、東袖塀から通りに沿って塀が続く。腰を大和張とし、上部は開口を穿つ土壁とする。温泉町の伝統的な街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007704"},{"id":"00007702","register_sub_id":"101","register_pk":"108684","name":"旅館金波楼本館","kana":"りょかんきんぱろうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県八代市日奈久上西町字西町又361他","lat":32.43284038,"lng":130.57392893,"geo_status":"db","era":"明治42／大正3増築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造3階建、瓦葺、建築面積568㎡","structure_material":"木造3階建","registered":"2009.04.28(平成21.04.28)","register_no":"43 － 0105","desc":"日奈久温泉に所在する大規模な木造３階建旅館。北側の通りに対して建つ凹型の建物とその北東角に付くＬ字型の棟からなる。屋根は寄棟や切妻を複雑に組み合わせる。通り側は各階に庇を付け、大きく開口を設け、ガラス戸をたて、開放的な外観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007702"},{"id":"00014440","register_sub_id":"101","register_pk":"511429","name":"若城金物店蔵","kana":"わかきかなものてんくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"熊本県","address":"熊本県宇城市小川町小川字上苅萱90","lat":32.58505278,"lng":130.70611389,"geo_status":"db","era":"元治元年（1864)","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積89㎡","structure_material":"土蔵造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"43 - 0196","desc":"薩摩街道沿いの商家の敷地東辺に建つ長大な米蔵。土蔵造二階建、切妻造桟瓦葺、南北妻側に下屋を設け、東面北隅に庇を掛けて引戸を建てる。内部は土間で上部吹抜とするが、元は各階板敷。一階は窓を設けず、木材を打ち付けて壁を保護し、米収納の様子を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014440"},{"id":"00014438","register_sub_id":"101","register_pk":"511427","name":"若城金物店厨房","kana":"わかきかなものてんちゅうぼう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"江戸","pref":"熊本県","address":"熊本県宇城市小川町小川字上苅萱90","lat":32.58516389,"lng":130.70625,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積37㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"43 - 0194","desc":"薩摩街道沿いの商家の台所棟で、店舗の背面側に中庭をはさんで建つ。二階建真壁造で南西に便所棟を付属し、切妻造目板瓦葺とする。一階は石貼り土間で東に煉瓦竈、西に井戸と流しを配す。二階は東半を吹抜、西半を板敷とする。往時の生活空間を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014438"},{"id":"00014437","register_sub_id":"101","register_pk":"511426","name":"若城金物店店舗兼主屋","kana":"わかきかなものてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県宇城市小川町小川字上苅萱90","lat":32.58531667,"lng":130.70616667,"geo_status":"db","era":"江戸末期／天保１３年(１８４２)増築・昭和42年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階一部平屋建、瓦葺、建築面積280㎡","structure_material":"木造2階一部平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"43 - 0193","desc":"薩摩街道に北面する商家。二階建、切妻造平入の東西棟店舗兼主屋に、切妻造妻入の南北棟倉庫が接続した大型町家。背面南西に角屋の続き間座敷を設けて庭に面して縁を廻す。間口長大で土間に太い梁を見せ、外壁は軒裏まで漆喰で塗り込めた重厚な構えの町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014437"},{"id":"00014439","register_sub_id":"101","register_pk":"511428","name":"若城金物店納屋","kana":"わかきかなものてんなや","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"熊本県","address":"熊本県宇城市小川町小川字上苅萱90","lat":32.58510556,"lng":130.70626389,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階一部平屋建、瓦葺、建築面積69㎡","structure_material":"木造2階一部平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"43 - 0195","desc":"薩摩街道沿いの商家の納屋。台所棟南に接続する切妻造目板瓦葺の南北棟で、西及び南面に庇を付す。北半を平屋建の味噌倉、南半を二階建とし、一階を開放的な物置、二階を居室とする。格子や突上窓を用いる伝統的な造りで、広大な屋敷構えの東辺を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014439"},{"id":"00005069","register_sub_id":"101","register_pk":"106059","name":"麻生家住宅主屋","kana":"あそうけじゅたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県豊後大野市三重町市場1090","lat":32.9768251,"lng":131.58088296,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積141㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"44 － 0114","desc":"敷地西端に商店街の道路に西面して南北棟で建つ。桁行７間，梁間５間の規模で，入母屋造，桟瓦葺，木造２階建で，正面に下屋半間を出す。側面及び２階を大壁とし二階軒裏を漆喰で塗り込め，塗屋造とする。醤油醸造関連施設として造られ，往時の繁栄を偲ばせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005069"},{"id":"00003180","register_sub_id":"101","register_pk":"104170","name":"岩尾家住宅（旧日本丸製薬所）主屋","kana":"いわおけじゅうたく（きゅうにほんがんせいやくしょ）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県日田市豆田町4-15","lat":33.32744206,"lng":130.93742655,"geo_status":"db","era":"大正後期／昭和初期増築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造3階建、瓦葺、建築面積171㎡","structure_material":"木造3階建","registered":"2003.01.31(平成15.01.31)","register_no":"44 － 0091","desc":"伝統的な町並みが残る豆田上町の中央にある薬局。主屋は大正後期に建てられた２階建，塗籠の町家で，昭和初期に３階の望楼が増築された。正面１階右端には唐破風の屋根を飾り，２階には銘木を多用した大広間を造る。豆田の天守閣として市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003180"},{"id":"00003182","register_sub_id":"101","register_pk":"104172","name":"岩尾家住宅（旧日本丸製薬所）土蔵","kana":"いわおけじゅうたく（きゅうにほんがんせいやくしょ）どぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県日田市豆田町4-15","lat":33.32753171,"lng":130.93744386,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造3階建、瓦葺、建築面積62㎡","structure_material":"土蔵造3階建","registered":"2003.01.31(平成15.01.31)","register_no":"44 － 0093","desc":"主屋北側に接してあり，道路側に妻を見せる３階建，切妻造，桟瓦葺の袖蔵。本来の用途である倉庫であるとともに，吹き抜けを持つ台所や座敷として主屋と一体となって使われる。主屋とともに豆田の町並み景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003182"},{"id":"00007438","register_sub_id":"101","register_pk":"108420","name":"宇野家住宅主屋（旧高瀬入早商店店舗兼主屋）","kana":"うのけじゅうたくしゅおく（きゅうたかせいりはやしょうてんてんぽけんしゅおく）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県日田市大字高瀬字徳行720-3","lat":33.305447,"lng":130.93959,"geo_status":"db","era":"昭和2／昭和57・平成19改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積147㎡","structure_material":"木造2階一部平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0164","desc":"三隈川南岸を並行に走る通りに北面する。入母屋造妻入桟瓦葺の木造２階建で、東面南寄りに切妻造平屋建の角屋を付ける。妻を漆喰仕上げとし、庇を３段の段差を付けたモルタル塗とする。２階は正面寄り三方を高欄付の縁として開放的に扱い、軽快な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007438"},{"id":"00000110","register_sub_id":"101","register_pk":"101100","name":"大分銀行赤レンガ館（旧二十三銀行本店・旧府内会館）","kana":"おおいたぎんこうあかれんがかん（きゅうにじゅうさんぎんこうほんてん・きゅうふないかいかん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県大分市府内町2-2-1","lat":33.23713952,"lng":131.60770466,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"鉄筋コンクリート造2階建、スレート及び瓦棒葺、建築面積775㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"44 － 0001","desc":"クラシックとゴシックの中間的なクイーンアン様式をもとに，ドームを載せる構成が特徴的。設計は多くの名作を残した辰野・片岡建築事務所である。昭和20年の戦災で内部は焼失したが，外壁を保存する形で修復され，平成５年に再度内部が改修された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000110"},{"id":"00006304","register_sub_id":"101","register_pk":"107287","name":"梶原家住宅主屋","kana":"かじわらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県速見郡日出町大字豊岡字本町988-1他","lat":33.359943,"lng":131.49766332,"geo_status":"db","era":"明治40頃／大正7頃増築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積135㎡","structure_material":"木造2階一部平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"44 － 0131","desc":"西側道路に面して建つ。妻入の町家で，桁行７間，梁間４間，木造２階建，入母屋造，桟瓦葺とする。広い玄関を構え，奥に書院，床の間付の客間をもつ。玄関正面に人見梁，持送りを付け，玄関脇は出格子とする。外壁及び妻面を漆喰塗とし，重厚な外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006304"},{"id":"00006305","register_sub_id":"101","register_pk":"107288","name":"梶原家住宅土蔵","kana":"かじわらけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県速見郡日出町大字豊岡字本町988-1他","lat":33.35984146,"lng":131.4977885,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"44 － 0132","desc":"主屋の東側に建つ。桁行４間半，梁間３間半規模で，木造平屋建，入母屋造，桟瓦葺とする。西側を廊下とし東側に８畳間２室の続き間座敷をとり，南端に床の間を付ける。北西隅を便所とし，敷地北側の廊下で主屋と繋がる。丁寧な造作で，落ち着いた外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006305"},{"id":"00008222","register_sub_id":"101","register_pk":"132747","name":"旧大分合同銀行社屋","kana":"きゅうおおいたごうどうぎんこうしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県豊後高田市中央通字横町691他","lat":33.55914657,"lng":131.44071891,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積153㎡","structure_material":"木造平屋一部2階建","registered":"2010.04.28(平成22.04.28)","register_no":"44 － 0175","desc":"市中心部の通り沿いに東面して建つ。正面８．５ｍ、平入の土蔵造平屋建と、背面に接続する入母屋造、木造２階建からなる。正面は白漆喰仕上げで、腰石貼とする。伝統意匠を基調としつつ、出桁の持送りなどに洋風意匠を取り入れ、近代的な街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008222"},{"id":"00007813","register_sub_id":"101","register_pk":"108794","name":"旧共同野村銀行社屋","kana":"きゅうきょうどうのむらぎんこうしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県豊後高田市新町字新町963-1","lat":33.5588644,"lng":131.43970858,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造一部鉄筋コンクリート造平屋建、瓦葺、建築面積160㎡","structure_material":"木造一部鉄筋コンクリート造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"44-0165","desc":"通りに北面する木造の旧銀行建築で、背面にコンクリート造金庫室を付ける。正面は腰を石貼とし、タイル貼の柱型をあらわし、モルタル仕上げのパラペットを立ち上げる。正側面に縦型窓を等間隔に配し、玄関上部に装飾柱を飾る。昭和面影を残す町並みの中核施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007813"},{"id":"00009097","register_sub_id":"101","register_pk":"162457","name":"旧竹屋書店店舗兼主屋","kana":"きゅうたけやしょてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県竹田市大字竹田町字本町386","lat":32.96716547,"lng":131.39277101,"geo_status":"db","era":"明治32年／昭和40年頃改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建、瓦葺、建築面積184㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0196","desc":"角地に建つ商家建築。間口１１ｍ奥行１３ｍの木造二階建。切妻造桟瓦葺で西正面に下屋を付ける。正面など一階はガラス戸をたて込み開放的に扱い、他は漆喰仕上げの大壁とする。正面には瓦庇を付ける連続窓を二箇所開け、特徴的な表構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009097"},{"id":"00009098","register_sub_id":"101","register_pk":"162458","name":"旧竹屋書店土蔵","kana":"きゅうたけやしょてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県竹田市大字竹田町字本町386","lat":32.96710812,"lng":131.39285704,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積19㎡","structure_material":"土蔵造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0197","desc":"主屋の背面南寄りから東に延びる上便所の東に接して建つ。南北棟の切妻造桟瓦葺。桁行５．２ｍ梁間３．７ｍの土蔵造平屋建。漆喰仕上げで、鉢巻をまわし、北妻面に出入口を穿つ。内部は中塗仕上げ。屋敷地内に残る小規模土蔵の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009098"},{"id":"00003183","register_sub_id":"101","register_pk":"104173","name":"隈まちづくりセンター黎明館","kana":"くままちづくりせんたーれいめいかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県日田市隈2-2-1","lat":33.31355013,"lng":130.93162679,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積91㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"44 － 0094","desc":"大分銀行日田支店として建設。木造２階建，寄棟造，桟瓦葺で，外壁に煉瓦タイルを張り，セセッション風に仕上げる。清水組の設計施工で，設計担当は小笹徳蔵。隈町２丁目の角地にあり，昭和１８年から近年までは浜田医院として長く市民に親しまれてきた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003183"},{"id":"00007431","register_sub_id":"101","register_pk":"108413","name":"後藤家住宅隠居座敷","kana":"ごとうけじゅうたくいんきょざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県日田市隈2-80他","lat":33.315361,"lng":130.929901,"geo_status":"db","era":"明治後期／昭和4・昭和52改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0157","desc":"主屋の後方、庄手川沿いに位置し、主屋と渡廊下で繋がる。桁行１２ｍ梁間６．０ｍ規模の木造平屋建、南北棟の切妻造桟瓦葺とする。川側の石垣は南側を川石練積、北側を布積とする。八畳２室の続き座敷で、東・北・西三方に榑縁を張り、北端に川への石段を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007431"},{"id":"00007432","register_sub_id":"101","register_pk":"108414","name":"後藤家住宅座敷蔵","kana":"ごとうけじゅうたくざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"大分県","address":"大分県日田市隈2-80他","lat":33.315441,"lng":130.929901,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積51㎡","structure_material":"木造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0158","desc":"隠居座敷の北面に接して建つ木造２階建。桁行８．７ｍ梁間６．５ｍ規模、東西棟の入母屋造桟瓦葺。川石を練積とする石垣上に建ち、１階は大壁造の土蔵、２階は真壁造の座敷とし、川側に縁を張る。棟の高い入母屋破風が川に臨み、河岸の景観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007432"},{"id":"00007430","register_sub_id":"101","register_pk":"108412","name":"後藤家住宅主屋","kana":"ごとうけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県日田市隈2-80他","lat":33.315414,"lng":130.930084,"geo_status":"db","era":"明治20／大正期改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積270㎡","structure_material":"木造2階一部平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0156","desc":"通りに東面して建つ。木造２階建の入母屋造妻入桟瓦葺で、南面に角屋を表と奥に出し、その間に坪庭を設ける。漆喰仕上げの大壁造とし、腰を海鼠壁とする。北側に土間、南にミセや居室、角屋に座敷飾りを構える座敷を配する。明治期における上質な町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007430"},{"id":"00007433","register_sub_id":"101","register_pk":"108415","name":"後藤家住宅東土蔵及び西土蔵","kana":"ごとうけじゅうたくひがしどぞうおよびにしどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県日田市隈2-192","lat":33.31552828,"lng":130.92992393,"geo_status":"db","era":"大正6／平成元移築改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積121㎡","structure_material":"土蔵造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0159","desc":"座敷蔵の北側、川沿いに南北棟の西土蔵、その東に東西棟の東土蔵が位置する。いずれも切妻造桟瓦葺の土蔵造２階建。外壁は漆喰仕上げで、腰石貼とし、窓には瓦庇を付ける。西土蔵は川側が、座敷蔵から連続する練積の石垣上に建つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007433"},{"id":"00000717","register_sub_id":"101","register_pk":"101707","name":"斉藤家住宅","kana":"さいとうけじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県臼杵市大字福良字屋敷余り212","lat":33.11613488,"lng":131.79401301,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造２階建，瓦葺，建築面積132㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"44 － 0040","desc":"臼杵の町の西の玄関口にあたる福良地区に建つ切妻造，２階建の町家で，１階軒廻りに小庇が付く。北側は宮の参道に面し，水切りの小庇を２段に付け意匠とした妻側及び背後に連なる高塀付きの付属屋を見せる。近年の修理工事で，弁柄塗りの表構えに再生された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000717"},{"id":"00009100","register_sub_id":"101","register_pk":"162460","name":"塩屋旧大蔵","kana":"しおやきゅうおおくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県竹田市大字竹田町字本町509","lat":32.96797322,"lng":131.39199453,"geo_status":"db","era":"江戸末期／昭和33年頃・平成23年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積118㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0199","desc":"路地の西側に建つ。桁行が東西で少し異なる台形平面になる木造二階建で、建築面積１１８㎡。切妻造桟瓦葺で、壁は大壁とし、漆喰で仕上げる。内部北半部を東西に分け、男女の浴場とする。内外に変遷を留め、竹田の町並みに彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009100"},{"id":"00003772","register_sub_id":"101","register_pk":"104762","name":"塩屋主屋","kana":"しおやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県竹田市大字竹田町字本町503","lat":32.96815208,"lng":131.39229357,"geo_status":"db","era":"元治2","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造2階建、瓦葺、建築面積93㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"44 － 0098","desc":"正面入母屋造，背面切妻造，２階建・妻入，桟瓦葺で，正面は街路に沿って壁面が斜めになり，１階の下屋庇は側面にも廻り込む。要所に水切庇付の小窓を配り，軒裏まで漆喰塗とした重厚なつくりとする。棟札から建築年代が明確で，当地域の商家建築の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003772"},{"id":"00009099","register_sub_id":"101","register_pk":"162459","name":"竹田市公民館竹田分館（旧一味楼）","kana":"たけたしこうみんかんたけたぶんかん（きゅういちみろう）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県竹田市大字竹田1918-1他","lat":32.9689036,"lng":131.39439083,"geo_status":"db","era":"大正2年頃／平成23年改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積233㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0198","desc":"稲葉川西岸に位置する。南北棟の入母屋造桟瓦葺、木造二階建で、南寄りの西面に玄関、東面に倉庫を付設。建築面積２３３㎡。一階は南北に座敷が並び、二階はステージをもつ大広間とする。九間に及ぶ杉磨丸太や桐など良材を贅沢に使う料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009099"},{"id":"00003638","register_sub_id":"101","register_pk":"104628","name":"筑紫亭主屋","kana":"ちくしていしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県中津市1692、1693、1694他","lat":33.60212141,"lng":131.18823531,"geo_status":"db","era":"大正3／大正11増築","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積413㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"44 － 0095","desc":"南北に細長い敷地北側にある。南と北に中庭を挟んで入母屋造，桟瓦葺，２階建の主体部が建ち，廊下で接続し，全体としては口ノ字型の平面になり，５２畳の大広間と２０畳の広間を２階に配している。良材を用い，造作にも凝った数寄屋風の意匠でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003638"},{"id":"00003639","register_sub_id":"101","register_pk":"104629","name":"筑紫亭離れ","kana":"ちくしていはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県中津市大字島田835-15、835-91","lat":33.60190809,"lng":131.18842466,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋一部2階建、瓦葺、建築面積125㎡","structure_material":"木造平屋一部2階建","registered":"2003.09.19(平成15.09.19)","register_no":"44 － 0096","desc":"主屋の後方，敷地を東西に流れる水路の南側にあり，主屋の増築に続いて建設されたと考えられる。２階建１棟と平屋建２棟を，縁や廊下で巧みに結んだ構成になる。主屋同様に数寄を凝らし，客室は各々異なるつくりの床で飾り，垂木や手摺などに磨丸太を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003639"},{"id":"00003640","register_sub_id":"101","register_pk":"104630","name":"筑紫亭塀","kana":"ちくしていへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県中津市1692、1693、1694","lat":33.60226848,"lng":131.18815986,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造、瓦葺、延長17m","structure_material":"木造","registered":"2003.09.19(平成15.09.19)","register_no":"44 － 0097","desc":"敷地北辺を画す延長１７ｍ，高さ３．１５ｍの塀で，中央に庇付の門口を構え，西側に通用口を設ける。桟瓦葺の小屋根を架けた真壁造で，腰までを割竹で覆い，上部に下地窓を設ける。正面を飾るに相応しい瀟洒で風格のある構成で，街路景観を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003640"},{"id":"00012666","register_sub_id":"101","register_pk":"367960","name":"とまや店舗兼主屋","kana":"とまやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県杵築市大字杵築字新町385","lat":33.41885,"lng":131.622192,"geo_status":"geocoded","era":"明治8年頃／昭和62年移築","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造2階建、瓦葺、建築面積118㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"44 － 0231","desc":"杵築旧城下の街路に北面して建つ商家主屋。入母屋造妻入の二階建。正面は上下階に繰形付持送の出桁で深い軒をつくり、二階は軒先まで塗込める。一階正面にミセ、奥に８畳と６畳を並べ、二階に座敷を設ける。伝統的な町家の形式を示し、城下町の景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012666"},{"id":"00002570","register_sub_id":"101","register_pk":"103560","name":"冨士屋旅館石垣","kana":"ふじやりょかんいしがき","category":"産業3次","subcategory":"その他工作物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県別府市大字鉄輪字ウカリユ735-1","lat":33.31688997,"lng":131.47812576,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"石造、折曲り延長71m","structure_material":"石造","registered":"2001.11.20(平成13.11.20)","register_no":"44 － 0072","desc":"敷地の東辺を限るジグザグ状折曲り延長７０ｍ程の石積擁壁で，間に石段１所を設ける。南端から石段の北３ｍ程までは亀甲積に近い丁寧な石積で，その北方は自然石の乱積とする。前門の前の石段とともにかってのアプローチ景観を今に伝えていて貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002570"},{"id":"00002569","register_sub_id":"101","register_pk":"103559","name":"冨士屋旅館石段","kana":"ふじやりょかんいしだん","category":"産業3次","subcategory":"その他工作物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県別府市大字鉄輪字ウカリユ735-1","lat":33.31681791,"lng":131.47810798,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"石造、13段、幅2.1m","structure_material":"石造","registered":"2001.11.20(平成13.11.20)","register_no":"44 － 0071","desc":"敷地東側の石畳道路から前門までの１４段の石段。石段幅は前門の間口に対応した２．１ｍで，踏石には幅４０ｃｍ，厚１５ｃｍ程度の板石，側石には１５ｃｍ角程度の長石を用い，石段北面は亀甲積に近い丁寧な石積面を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002569"},{"id":"00002567","register_sub_id":"101","register_pk":"103557","name":"冨士屋旅館主屋","kana":"ふじやりょかんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県別府市大字鉄輪字ウカリユ735-1","lat":33.316875,"lng":131.477951,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造2階建、瓦葺、建築面積361㎡","structure_material":"木造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"44 － 0069","desc":"別府八湯の中核をなす鉄輪温泉の老舗旅館。東面を正面とした南北棟，寄棟造，木造２階建本館部の南に棟を落とした東西棟，寄棟造の木造２階建が取付く。大正期に南部に入母屋造の玄関を増築するが，東面中央の入母屋造式台玄関跡が当旅館の格式を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002567"},{"id":"00002568","register_sub_id":"101","register_pk":"103558","name":"冨士屋旅館前門","kana":"ふじやりょかんまえもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県別府市大字鉄輪字ウカリユ735-1","lat":33.31683291,"lng":131.47809498,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造、間口2.1m","structure_material":"木造","registered":"2001.11.20(平成13.11.20)","register_no":"44 － 0070","desc":"主屋の旧式台玄関に向き合う位置に建つ。かっては，いでゆ坂から敷地東側の石畳を通り，石段を昇って門をくぐるアプローチをとった。間口１間幅の１間１戸，桟瓦葺の薬医門で，敷地東側の道路からは一段高い位置にあって格好のアイストップにもなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002568"},{"id":"00006468","register_sub_id":"101","register_pk":"107451","name":"別府タワー","kana":"べっぷたわー","category":"産業3次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"大分県","address":"大分県別府市北浜三丁目10-2","lat":33.281742,"lng":131.505936,"geo_status":"db","era":"昭和32／平成16改修","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄塔 鉄骨造、高さ73m、脚間15m、展望台付、下部構造 鉄骨鉄筋コンクリート造4階建、面積384㎡","structure_material":"鉄塔 鉄骨造","registered":"2007.10.02(平成19.10.02)","register_no":"44 － 0133","desc":"国道１０号に面して建つ。ＳＲＣ造４階建の建屋の上に高さ７４ｍの鉄塔を組み、総高９０ｍとする。塔身の断面は下から八角形、四角形、三角形と変化し、展望室のカーテンウォールには俯瞰を考慮し傾斜を付ける。別府のランドマークとして広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006468"},{"id":"00007437","register_sub_id":"101","register_pk":"108419","name":"山田家住宅石垣及び煉瓦塀","kana":"やまだけじゅうたくいしがきおよびれんがべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県日田市隈1-214-1","lat":33.31175003,"lng":130.9323314,"geo_status":"db","era":"大正10・昭和28","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"石垣 石造、延長25m、石段付 塀 煉瓦造、延長26m","structure_material":"石垣 石造","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0163","desc":"三隈川沿いに築かれる。石垣は東西２５ｍで、中央で川側に突き出し、石垣に沿って石段を設ける。川石を練積とし、高さは３ｍ前後。煉瓦塀は高さ１ｍの長手積で、石段の降口部分に両開の鉄扉を吊る。明るい煉瓦塀が河川景観に彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007437"},{"id":"00007436","register_sub_id":"101","register_pk":"108418","name":"山田家住宅井戸","kana":"やまだけじゅうたくいど","category":"産業3次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県日田市隈1-214-1","lat":33.311867,"lng":130.932404,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"切石、面積1.8㎡、上屋付","structure_material":"切石","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0162","desc":"主屋後方、敷地のほぼ中央に位置する。切石を相欠に組む、方１．４ｍ高さ０．６ｍの井戸枠を中心に、西に沓石を置き、その周囲に東西２．８ｍ南北２．２ｍで、石敷の洗い場を設ける。石材は地元産の安山岩。上屋は井戸枠に柱を建て、腕木で切妻屋根を支える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007436"},{"id":"00007434","register_sub_id":"101","register_pk":"108416","name":"山田家住宅主屋","kana":"やまだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県日田市隈1-214-1","lat":33.31197,"lng":130.932465,"geo_status":"db","era":"文化13","year":1816,"year_source":"db","year_min":1816,"year_max":1816,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積210㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0160","desc":"通りに北面して建つ間口２２ｍに及ぶ大型の平入町家。切妻造瓦葺で、前後に深い下屋を付ける。漆喰仕上げの大壁造で、腰海鼠壁。当初は中央に通り土間、西に続き座敷、東に２列３室の居室を設けた。正面は下屋を本瓦葺とし、軒の低い重厚な構えにつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007434"},{"id":"00007435","register_sub_id":"101","register_pk":"108417","name":"山田家住宅土蔵","kana":"やまだけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県日田市隈1-214-1","lat":33.311844,"lng":130.932343,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積67㎡","structure_material":"土蔵造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0162","desc":"敷地後方の三隈川近くに建つ。桁行１０ｍで、南半部が梁間６．２ｍ、北半部が５．２ｍ。屋根は段違い切妻造、南を桟瓦葺、北を本瓦葺とする。土蔵造２階建で、南半部の２階を居室とする。外壁は漆喰仕上げ、内壁は中塗仕上げ。災害の歴史を伝える遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007435"},{"id":"00015398","register_sub_id":"101","register_pk":"532522","name":"旧黒木家住宅店舗兼主屋","kana":"きゅうくろぎけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県児湯郡高鍋町大字高鍋町598-4","lat":32.12478889,"lng":131.50817778,"geo_status":"db","era":"明治33年／大正前期・令和6年改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積174㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"45 - 0115","desc":"高鍋城下の旧街道に東面して建つ、肥料製造販売業等を営んだ旧店舗兼主屋。桁行八間半の木造二階建寄棟造平入桟瓦葺で正背面に下屋を付ける。外壁は下見板張で、二階は縦長の上下窓を密に配した洋風の外観。町内最大級の間口の町家で当地の繁栄を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015398"},{"id":"00006273","register_sub_id":"101","register_pk":"107257","name":"旧後藤家商家交流資料館石塀","kana":"きゅうごとうけしょうかこうりゅうしりょうかんいしべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県都城市高城町高城2857","lat":31.80190067,"lng":131.13152078,"geo_status":"db","era":"明治33／平成13移設","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"石造、延長60m","structure_material":"石造","registered":"2007.07.31(平成19.07.31)","register_no":"45 － 0045","desc":"敷地の南辺，西辺，北辺及び東辺の一部を廻る石塀である。延長６０ｍで，基礎石の上に切石４段を積み，頂部に笠石を載せ，高さ１．７ｍ，厚さ０．３ｍとする。石の材質は凝灰岩で，地域内に多くみられ，地域的な特色をもった石塀のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006273"},{"id":"00006128","register_sub_id":"101","register_pk":"107112","name":"旧後藤家商家交流資料館本館","kana":"きゅうごとうけしょうかこうりゅうしりょうかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県都城市高城町高城2857","lat":31.80198063,"lng":131.131607,"geo_status":"db","era":"明治33／平成13曳家","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積231㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"45 － 0044","desc":"北側道路に面して建つ。桁行８間，梁間７間半の規模で，木造２階建，入母屋造，桟瓦葺とし，塗屋造とする。東側に通り土間をとり，周囲に半間幅の土間を廻す。２階の縁下には下屋を設け，重厚な屋根形式をつくる。意匠，材質ともに優秀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006128"},{"id":"00000920","register_sub_id":"101","register_pk":"101910","name":"杉村金物本店主屋","kana":"すぎむらかなものほんてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市油津1-6-12","lat":31.58377558,"lng":131.40321984,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造３階建，瓦葺，建築面積185㎡","structure_material":"木造３階建","registered":"1998.10.09(平成10.10.09)","register_no":"45 － 0003","desc":"油津の港に通じる道路に面した角地に建つ木造３階建の店舗兼用住宅。１階を店舗，２・３階を住居にあてる。縦長の窓や隅の石張り風の仕上げなど洋風の意匠を取り込み，外壁を銅板で覆った外観に特徴があり，町並でひときわ目立つ存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000920"},{"id":"00000921","register_sub_id":"101","register_pk":"101911","name":"杉村金物本店倉庫","kana":"すぎむらかなものほんてんそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"宮崎県","address":"宮崎県日南市油津1-6-12","lat":31.5837535,"lng":131.40311389,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"煉瓦造３階建，瓦葺，建築面積185㎡","structure_material":"煉瓦造３階建","registered":"1998.10.09(平成10.10.09)","register_no":"45 － 0004","desc":"主屋の西に隣接して建つ。煉瓦造３階建のせいの高い倉庫で，２階と３階の間は石材を帯状にまわして外観に変化をもたせている。主屋とともに町並でひときわ目立つ存在で，赤煉瓦で開口部の少ない外観の意匠は，銅板で覆った主屋と好対照をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000921"},{"id":"00005523","register_sub_id":"101","register_pk":"106511","name":"鈴木旅館北離れ","kana":"すずきりょかんきたはなれ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市油津1-2-7","lat":31.58419782,"lng":131.40257377,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階一部平屋建、瓦葺、建築面積63㎡","structure_material":"木造2階一部平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0032","desc":"西本館の北側に建ち，桁行４間，梁間３間の規模で，木造２階建，入母屋造，桟瓦葺とし，１，２階に客室をそれぞれ１室とする。北方に木造平屋建の小規模な客室棟が付属する。昭和初期の油津港の繁栄した頃に増築された離れで，当時の旅館の発展を知る上で貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005523"},{"id":"00005525","register_sub_id":"101","register_pk":"106513","name":"鈴木旅館土蔵","kana":"すずきりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市油津1-2-7","lat":31.58426654,"lng":131.40251038,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0034","desc":"敷地の北西隅に建ち，桁行６ｍ，梁間４ｍの規模で，土蔵造２階建，切妻造，桟瓦葺とする。外壁を白漆喰塗とし，鉢巻きを廻し，妻側に小さな窓を開く。南妻側に戸口を設け，一部煉瓦貼りとする。小規模ではあるが，昭和期の旅館の繁栄を物語る建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005525"},{"id":"00005522","register_sub_id":"101","register_pk":"106510","name":"鈴木旅館西本館","kana":"すずきりょかんにしほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市油津1-2-7","lat":31.58400214,"lng":131.40259375,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積125㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0031","desc":"南側道路に面して，本館の西側に建つ。桁行５間半，梁間５間半の規模で，木造２階建，寄棟造，桟瓦葺とする。１階は道路側に表玄関を構え，西半を調理場とし，２階に客間５室をとる。昭和初期に本館の西側に増築されたもので，旅館の発展を今日に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005522"},{"id":"00005524","register_sub_id":"101","register_pk":"106512","name":"鈴木旅館東離れ","kana":"すずきりょかんひがしはなれ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市油津1-2-6","lat":31.58406051,"lng":131.40277289,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0033","desc":"主屋の東側に近接して建ち，桁行４間半，梁間２間半の規模で，木造平屋建，入母屋造，桟瓦葺とする。座敷と洋間を続け，浴室を付ける。妻壁を漆喰塗りとし，堅牢なつくりで，旅館繁栄の時期に建てられ，小規模ではあるが独立した離れの旅館形式を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005524"},{"id":"00005521","register_sub_id":"101","register_pk":"106509","name":"鈴木旅館本館","kana":"すずきりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市油津1-2-7","lat":31.58408165,"lng":131.40268189,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積82㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0030","desc":"南側道路からやや後退して建ち，南北８間，東西６間の規模で，入母屋造東西棟の２棟を南北棟の両下造でつなぐ。木造２階建，桟瓦葺とする。１階前方に内玄関，浴室を置き，奥を大広間とし，２階に客室５室を置く。油津の明治期からの老舗旅館として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005521"},{"id":"00009866","register_sub_id":"101","register_pk":"195695","name":"奈良家住宅主屋","kana":"ならけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県宮崎市旭1-106","lat":31.91008891,"lng":131.42517298,"geo_status":"db","era":"昭和初期／昭和39移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積104㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"45 － 0077","desc":"県庁前の通りに北面し、木造二階建、入母屋造妻入、桟瓦葺で、正面に庇を付す。一階北寄りの店舗は、正面に格子付の出窓を設け、ガラス戸をたて、内部に格天井を張る。一階後方と二階には丁寧な造作の和室を配する。中心市街地の近代化を伝える店舗兼用住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009866"},{"id":"00009867","register_sub_id":"101","register_pk":"195696","name":"奈良家住宅別棟","kana":"ならけじゅうたくべっとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"宮崎県","address":"宮崎県宮崎市旭一丁目106","lat":31.9100675,"lng":131.42539427,"geo_status":"db","era":"昭和10頃／昭和39移築","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積150㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"45 － 0078","desc":"主屋の東隣に建つ。木造二階建、入母屋造桟瓦葺で、北西に玄関を張出し、下階に下屋、上階に窓庇を廻らす。一階南寄りに和室二室を並べて縁を廻らし、二階は和室五室を配する。各所の欄間に菊花や扇面、格狭間意匠をあしらうなど、室内造作も洗練されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009867"},{"id":"00005526","register_sub_id":"101","register_pk":"106514","name":"満尾書店","kana":"みつおしょてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市油津1-9","lat":31.58342506,"lng":131.40330058,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階一部3階建、瓦葺、建築面積169㎡、地下室付","structure_material":"木造2階一部3階建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0035","desc":"南東の角地に建ち，桁行７間，梁間６間の規模で，木造２階一部３階建，寄棟造，桟瓦葺とし，小屋組をトラス構造とする。南東隅と東側を店とし，外壁をモルタル塗人造石洗い出しとし，２階に縦長の窓及び柱形を等間隔に並べ，洋風意匠とした商店建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005526"},{"id":"00004872","register_sub_id":"101","register_pk":"105862","name":"池田家住宅石倉","kana":"いけだけじゅうたくいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"鹿児島県","address":"鹿児島県霧島市横川町中ノ小字上岸田11-1","lat":31.90708485,"lng":130.70146992,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木骨石造2階建、瓦葺、建築面積46㎡","structure_material":"木骨石造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"46 － 0018","desc":"主屋の北方に位置し，東西棟で東妻面を通りに見せて建つ。桁行５間梁間２間半，切妻造，桟瓦葺の２階建で，床組や小屋組を石造外周壁の内側に沿わせた木柱で支持する木骨石造の倉庫。平入で南面に戸口を設け，外部の腰は石積を露わにし，上部は漆喰塗とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004872"},{"id":"00004871","register_sub_id":"101","register_pk":"105861","name":"池田家住宅主屋","kana":"いけだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県霧島市横川町中ノ小字上岸田11-1","lat":31.90699122,"lng":130.70150886,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造2階建、瓦葺、建築面積87㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"46 － 0017","desc":"桁行６間半梁行６間半規模，入母屋造，桟瓦葺の木造２階建で，通りに東面して建つ。１階は表側から北側にかけて土間を設け，南側に座敷を配した伝統的町家のつくりになるが，２階はたちの高い下見板張に上げ下げ窓を並べた洋風のつくりで際立った存在になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004871"},{"id":"00016758","register_sub_id":"101","register_pk":"579242","name":"小牧醸造石蔵","kana":"こまきじょうぞういしぐら","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県薩摩郡さつま町時吉字穴川口12-1他","lat":31.912787,"lng":130.461544,"geo_status":"db","era":"大正7年頃／平成9年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造平屋建、セメント瓦葺、建築面積125㎡","structure_material":"石造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"46 - 0130","desc":"川内川と穴川の合流地に位置する焼酎の造酒屋の石蔵。大正の火災後の再建と伝え、溶結凝灰岩の組積造とし耐火性を高める。小屋は木造キングポスト・トラスを組み、切妻造の屋根を架ける。当地域の近代期に特有の石蔵で、川内川河畔の歴史的な景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016758"},{"id":"00016759","register_sub_id":"101","register_pk":"579243","name":"小牧醸造煉瓦造煙突","kana":"こまきじょうぞうれんがづくりえんとつ","category":"産業3次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県薩摩郡さつま町時吉字穴川口12-8","lat":31.912702,"lng":130.461497,"geo_status":"db","era":"大正7年頃／平成5年移築","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"煉瓦造、高さ8.8m","structure_material":"煉瓦造","registered":"2026.07.09(令和8.07.09)","register_no":"46 - 0131","desc":"醸造用のボイラーにかつて併設していた煉瓦造の煙突。石蔵の南西に建つ。基部は一辺一・一五メートルの方形で高さ八・七六メートル。イギリス積で上部を窄め、頂部に蛇腹を廻らし装飾とする。造酒屋のランドマークとして親しまれる、貴重な煉瓦造の煙突。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016759"},{"id":"00007442","register_sub_id":"101","register_pk":"108424","name":"坂本家住宅主屋","kana":"さかもとけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県指宿市西方4681","lat":31.27722104,"lng":130.61866306,"geo_status":"db","era":"大正11／昭和28改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積155㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"46 － 0078","desc":"通りに南面して建つ。間口１０ｍ奥行１３ｍ規模。入母屋造妻入桟瓦葺で、四周に庇をまわし、正面にはさらに短い庇を付ける特徴的な外観を構成する。外壁は西面が切石積上を大壁造、正面は奥行７０㎝ほどを吹放ちで開放的にし、その奥北寄りには摺上げ戸を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007442"},{"id":"00007441","register_sub_id":"101","register_pk":"108423","name":"中俣家住宅主屋","kana":"なかまたけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県指宿市西方字宮ヶ濱中4674","lat":31.27678686,"lng":130.61929609,"geo_status":"db","era":"明治後期／昭和36移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積286㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"46 － 0077","desc":"通りに南面して建つ。間口１７ｍ奥行１５ｍと規模の大きい平入町家。屋根は桟瓦葺で、各面で異なる複雑な構成をもつ。正面は東切妻西入母屋造に庇をまわし、さらに庇を付ける。妻や軒を漆喰で塗り込め、正面両隅を切石積とする。屋根が重なる独特の外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007441"},{"id":"00007439","register_sub_id":"101","register_pk":"108421","name":"丸十金物百貨店店舗","kana":"まるじゅうかなものひゃっかてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県指宿市西方4826","lat":31.27576296,"lng":130.62039748,"geo_status":"db","era":"明治後期／昭和33改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋一部2階建、瓦葺、建築面積175㎡","structure_material":"木造平屋一部2階建","registered":"2008.10.23(平成20.10.23)","register_no":"46 － 0075","desc":"通りに北面して建つ。間口１１ｍの木造平屋一部２階建、切妻造妻入桟瓦葺。北半部を土間床のミセとし、両側面の壁面に棚をつくる。南半部は西に通り土間を設け、東側に田の字型に４室の居室を配する。正面の開放的な側まわりと大きな妻壁が印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007439"},{"id":"00007440","register_sub_id":"101","register_pk":"108422","name":"丸十金物百貨店蔵","kana":"まるじゅうかなものひゃっかてんみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"鹿児島県","address":"鹿児島県指宿市西方4826","lat":31.27568407,"lng":130.62033959,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"46 － 0076","desc":"店舗の後方に位置する。桁行６．３ｍ梁間５．２ｍの土蔵造２階建で、南北棟の切妻造桟瓦葺とする。外壁は切石積基礎をまわし、漆喰仕上げ。東面北寄りを出入口とし、引戸をたてる。内部も漆喰仕上げで、１階は土間床とする。商品の保管庫として使われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007440"},{"id":"00007443","register_sub_id":"101","register_pk":"108425","name":"蜷川菓子店店舗兼主屋","kana":"みながわかしてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県指宿市西方字仮屋ノ下4682","lat":31.27735591,"lng":130.61850518,"geo_status":"db","era":"大正2／昭和36改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積122㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"46 － 0079","desc":"通りに南面して建つ。間口１１ｍ奥行９．９ｍ規模の平入町家。前寄りにミセを設け、奥は通り土間と居室とする。屋根は桟瓦葺で、西面入母屋造、東面切妻造とし、側・背面三方に庇を付けるが、正面は道路拡幅に伴い改変された。妻は破風まで一連で塗り込める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007443"},{"id":"00001027","register_sub_id":"101","register_pk":"102017","name":"南日本銀行本店","kana":"みなみにほんぎんこうほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県鹿児島市山下町1-1","lat":31.59463614,"lng":130.55688013,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造６階建，建築面積1333㎡","structure_material":"鉄筋コンクリート造６階建","registered":"1998.12.11(平成10.12.11)","register_no":"46 － 0004","desc":"鹿児島無尽株式会社鹿児島支店として建設。３階分通しのコリント式列柱による主階層，アーチ窓を重ねたアチック層，曲面構成の塔屋との対比に妙味が感じられる。設計は元鹿児島県技師の三上昇。三面が道路に面することで格好のランドマークともなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001027"},{"id":"00004873","register_sub_id":"101","register_pk":"105863","name":"森山家住宅石倉","kana":"もりやまけじゅうたくいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"鹿児島県","address":"鹿児島県霧島市横川町中ノ小字諏訪985","lat":31.90333222,"lng":130.70106507,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木骨石造2階建、瓦葺、建築面積153㎡","structure_material":"木骨石造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"46 － 0019","desc":"敷地の裏手に位置する。東西棟，切妻造，桟瓦葺，平入の内部に中二階を設けた木骨石造倉庫で，南面に下屋庇を差し掛けてアーチ形の戸口を２箇所設ける他，下屋西端を石壁で囲い庫室とする。桁行９間梁間４間規模と大きく，商家の繁栄振りを物語っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004873"},{"id":"00014989","register_sub_id":"101","register_pk":"519249","name":"沖縄ホテル大道門","kana":"おきなわほてるうふどーもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"沖縄県","address":"沖縄県那覇市字大道上大道原35","lat":26.21779167,"lng":127.70008889,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造、瓦葺、間口5.9m","structure_material":"鉄筋コンクリート造","registered":"2024.03.06(令和6.03.06)","register_no":"47 - 0091","desc":"道路から敷地に至る通路にあるホテル表門。一間腕木門形式で鉄筋コンクリート造の角柱上部に腕木を挿し軒桁を受ける。屋根は切妻造琉球赤瓦葺で両妻に降棟をつけ大棟には鬼瓦を据える。沖縄の伝統建築の意匠で、戦後沖縄を代表するホテル入口を飾る大道門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014989"},{"id":"00014990","register_sub_id":"101","register_pk":"519250","name":"沖縄ホテル瓦石垣","kana":"おきなわほてるかわらいしがき","category":"産業3次","subcategory":"その他工作物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和中","pref":"沖縄県","address":"沖縄県那覇市字大道上大道原35","lat":26.21795556,"lng":127.699925,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"石造及びコンクリート造、瓦葺、総延長92m","structure_material":"石造及びコンクリート造","registered":"2024.03.06(令和6.03.06)","register_no":"47 - 0092","desc":"旅館棟の敷地外周を廻る石垣。高さ１・８メートル、総延長９２メートル。コンクリート造壁体に琉球石灰岩を積み、屋根は琉球赤瓦で葺き、棟頂部や端部は砂漆喰で塗込める。長大な石垣で大道門と一体となってホテルの表構えを整え、沖縄らしい景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014990"},{"id":"00014987","register_sub_id":"101","register_pk":"519247","name":"沖縄ホテル旅館棟","kana":"おきなわほてるりょかんとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"沖縄県","address":"沖縄県那覇市字大道上大道原35","lat":26.21809444,"lng":127.70015,"geo_status":"db","era":"昭和36年／平成5年改修","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積828㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2024.03.06(令和6.03.06)","register_no":"47 - 0089","desc":"安里駅北東の市街地に位置する昭和戦前から続くホテル。設計は仲座久雄。西に開いたコの字形平面で、中央棟に吹抜の玄関ホールと階段、北棟と南棟に客室を配す。各階窓上には庇を廻らし、中空ブロックで飾った壁面やバルコニーなど、仲座らしい特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014987"},{"id":"00014988","register_sub_id":"101","register_pk":"519248","name":"沖縄ホテルレンガ棟","kana":"おきなわほてるれんがとう","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和中","pref":"沖縄県","address":"沖縄県那覇市字大道上大道原35","lat":26.21805,"lng":127.70071389,"geo_status":"db","era":"昭和24年頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"鉄筋コンクリート造及び煉瓦造2階建、瓦葺、建築面積103㎡","structure_material":"鉄筋コンクリート造及び煉瓦造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"47 - 0090","desc":"敷地南東に位置する２階建切妻造桟瓦葺。一階は鉄筋コンクリートのラーメン構造で、煉瓦積を化粧で現し、二階は煉瓦造とした混構造。小屋は木造トラス組。外壁に大きめの矩形開口を開け、各階2室とする。戦後沖縄におけるホテル発祥の遺例として希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014988"},{"id":"00009109","register_sub_id":"101","register_pk":"164662","name":"高龍寺位牌堂","kana":"こうりゅうじいはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"北海道","address":"北海道函館市船見町21-1他","lat":41.76904461,"lng":140.70010639,"geo_status":"db","era":"昭和8年／平成4年・平成9年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造地上1階地下1階建、瓦葺、建築面積161㎡、左右回廊付","structure_material":"木造地上1階地下1階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"開山堂と金毘羅堂の間に西面して建ち、南北面に開山堂と金毘羅堂へ至る廊下を附属する。桁行5間梁間4間、入母屋造、向拝一間付、桟瓦葺で、鉄筋コンクリート造の地階を持ち、上下階とも内部は位牌を安置する。向拝の虹梁木鼻や虹梁上の彫刻に技巧を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009109"},{"id":"00009102","register_sub_id":"101","register_pk":"164655","name":"高龍寺開山堂","kana":"こうりゅうじかいざんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"北海道","address":"北海道函館市船見町21-1他","lat":41.76893753,"lng":140.70030864,"geo_status":"db","era":"明治30年頃／平成4年・平成9年改修","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積156㎡","structure_material":"煉瓦造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本堂の北東側に西面する煉瓦造の堂で、土蔵造風に漆喰仕上とする。桁行14.2メートル梁間9.9メートル、寄棟造桟瓦葺で、銅板葺の一間向拝を設ける。内部は正面1間通を廊下とし、堂内に羅漢像を祀る。函館市内に残る煉瓦造建築の古例となる遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009102"},{"id":"00009105","register_sub_id":"101","register_pk":"164658","name":"高龍寺金毘羅堂","kana":"こうりゅうじこんぴらどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"北海道","address":"北海道函館市船見町21-3","lat":41.76916001,"lng":140.69993091,"geo_status":"db","era":"大正6年／平成8年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"山門の東に西面して建つ桟瓦葺の堂。縦長平面の内陣正面に、方3間、入母屋造平入の大間を接続して丁字形をなし、南東に外単を張出す。大間の正面には軒唐破風付の向拝を付し、千鳥破風を重ねる。澤田吉平を棟梁とし、高龍寺境内で最も装飾的な建築のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009105"},{"id":"00009103","register_sub_id":"101","register_pk":"164656","name":"高龍寺山門及び袖塀","kana":"こうりゅうじさんもんおよびそでへい","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道函館市船見町21-3","lat":41.76906186,"lng":140.69966024,"geo_status":"db","era":"明治43年頃／平成9年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"山門 木造、瓦葺、面積35㎡ 袖塀 木造、瓦葺、総延長29m、潜戸付","structure_material":"山門 木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"境内正面に北面して建つ入母屋造桟瓦葺の木造8脚門で、軸部は禅宗様を基調とし、門の左右に桟瓦葺の袖塀を延ばす。本堂を手がけた篠田宗吉の次代となる5代宗吉が棟梁を務めた。蟇股や欄間等に、雲龍や獅子、花鳥等の彫刻を施す、装飾豊かな門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009103"},{"id":"00009107","register_sub_id":"101","register_pk":"164660","name":"高龍寺鐘楼","kana":"こうりゅうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道函館市船見町21-3","lat":41.7688947,"lng":140.6995258,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造、銅板葺、面積14㎡","structure_material":"木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"山門の西に建つ。方1間、入母屋造銅板葺で、布石積基壇上に建ち、軸部は禅宗様を基調とする。柱間は吹放ちとし、組物は二手先で、内部は格天井を張る。細部意匠は山門や金毘羅堂と一連の絵様をもち、水盤舎同様、澤田吉平ら越後大工の普請と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009107"},{"id":"00009106","register_sub_id":"101","register_pk":"164659","name":"高龍寺水盤舎","kana":"こうりゅうじすいばんしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道函館市船見町21-3","lat":41.76900832,"lng":140.69987142,"geo_status":"db","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造、銅板葺、面積8.7㎡、水盤付","structure_material":"木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"金毘羅堂と位牌堂間の前面に南北棟で建つ。方1間入母屋造銅板葺で、東西面に軒唐破風を付す。柱間を吹放ちとし、三斗上に小組格天井を張る。蟇股などの立体的で充実した彫刻は山門や金毘羅堂と類似し、澤田吉平ら越後大工による普請と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009106"},{"id":"00009110","register_sub_id":"101","register_pk":"164663","name":"高龍寺土塀","kana":"こうりゅうじどべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道函館市船見町21-3","lat":41.76926112,"lng":140.69981744,"geo_status":"db","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土塀、瓦葺、総延長53m","structure_material":"土塀","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"境内の北辺、山門袖塀の左右にのびる土塀。高さ3.7メートルで、長さは東側23.7メートル西側29.2メートルを測る。布石積基壇上に建ち、壁は真壁漆喰仕上げで腰を簓子下見板張とする。桟瓦葺屋根の棟には青海波を積み、落ち着いた風格を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009110"},{"id":"00009104","register_sub_id":"101","register_pk":"164657","name":"高龍寺防火塀","kana":"こうりゅうじぼうかべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道函館市船見町21-1他","lat":41.76921507,"lng":140.70008002,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦造、瓦葺、総延長154m","structure_material":"煉瓦造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"境内の東面及び北面西側を画す煉瓦塀。北面西側塀はフランス積とし、延長約104メートル、高さ約3メートル。東面塀は延長約50メートル、高さ約7メートル、イギリス積とする。延焼を防止するため設けられた、大火が頻発した近代函館を象徴する遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009104"},{"id":"00009108","register_sub_id":"101","register_pk":"164661","name":"高龍寺宝蔵","kana":"こうりゅうじほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道函館市船見町21-3","lat":41.76881761,"lng":140.69939398,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積63㎡","structure_material":"煉瓦造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"鐘楼の西に建つ煉瓦造の蔵。桁行9.7メートル、梁間6.1メートルの本体部は、2階建、切妻造桟瓦葺で、壁は漆喰で仕上げ、腰を簓子下見張とする。東妻に煉瓦壁を現した切妻造の蔵前を附属する。耐火性と景観に配慮し、煉瓦造を用いた独特の形式になる蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009108"},{"id":"00009101","register_sub_id":"101","register_pk":"164654","name":"高龍寺本堂","kana":"こうりゅうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道函館市船見町21-1他","lat":41.76866389,"lng":140.70021347,"geo_status":"db","era":"明治32年／昭和63年増築、昭和61年・平成8年・平成11年改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積526㎡、左右回廊付","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"函館山麓に北面して建ち、桁行9間梁間8間、入母屋造、正面向拝付、桟瓦葺で、周囲に下屋と縁を廻らし、東西に回廊を付属する。9室構成の堂内は、軸部木太く雄大で、棟梁の篠田宗吉以下、越後の工匠が関わった。大規模で装飾性豊かな近代の曹洞宗本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009101"},{"id":"00002500","register_sub_id":"101","register_pk":"103490","name":"最創山光岸寺本堂","kana":"さいそうざんこうがんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道旭川市東鷹栖東1条3丁目272-1","lat":43.824799,"lng":142.417664,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積592㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"01 － 0047","desc":"市北東部，国道４０号に面する境内の奥に建つ。正面は欄間等に丁寧な彫物を施した桁行３間の向拝が唐破風屋根に覆われる。本堂は立ちが高く，軒下の小壁に蟇股を配した裳階を廻し，組物と蟇股を多用した華やかな内部空間をもつ。道内で有数の本格的寺院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002500"},{"id":"00005790","register_sub_id":"101","register_pk":"106778","name":"順誓寺本堂","kana":"じゅんせいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道網走郡津別町字新町16","lat":43.70988818,"lng":144.02547003,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積203㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"01 － 0093","desc":"境内奥寄りに東南に面して建つ浄土真宗本堂。桁行７間，梁間７間，正面向拝付，切妻造，鉄板葺。内部柱を円柱とし，外陣では入側柱を成の高い虹梁で固める。内外陣境の彫刻欄間の上部にも絵様虹梁と大斗実肘木を入れ，全体に堅牢で華やかなつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005790"},{"id":"00007711","register_sub_id":"101","register_pk":"108693","name":"正行寺鐘楼","kana":"しょうぎょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道厚岸郡厚岸町梅香1-19他","lat":43.03622622,"lng":144.84622542,"geo_status":"db","era":"明治41／大正12・平成20改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造、銅板葺、面積7.5㎡","structure_material":"木造","registered":"2009.08.07(平成21.08.07)","register_no":"01-0103","desc":"北面する本堂の北西に南北棟で建つ。入母屋造銅板葺とする方一間の吹放ち鐘楼。唐戸面取の方柱を四方転びに建て、足固貫と内法貫、頭貫、台輪で固める。三斗組で中備に蟇股を配し、一軒疎垂木とし、格天井を張る。明治期に整えられた伽藍景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007711"},{"id":"00014991","register_sub_id":"101","register_pk":"529269","name":"清隆寺本堂","kana":"せいりゅうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道根室市松本町二丁目1-1他","lat":43.328575,"lng":145.57568056,"geo_status":"db","era":"大正14年／昭和50年代改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積258㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"01 - 0170","desc":"根室市街地に位置する真言宗寺院本堂。入母屋造鉄板葺で北面に軒唐破風付向拝を配し千鳥破風を付す。向拝虹梁、木鼻、懸魚の獅子、龍、鳳凰など彫刻秀逸。内部は前方を参詣間、後方を内陣・脇内陣とし内陣を前方に張出す。気仙大工花輪喜久蔵の道内作の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014991"},{"id":"00000720","register_sub_id":"101","register_pk":"101710","name":"日本基督教団札幌教会（旧札幌美以教会堂）","kana":"にほんきりすときょうだんさっぽろきょうかい（きゅうさっぽろめそじすときょうかいどう）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道札幌市中央区北1条東1","lat":43.06351193,"lng":141.35710071,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"石造平屋建，鉄板葺，建築面積233㎡","structure_material":"石造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"01 － 0008","desc":"市街地に建つ教会。木造の教会が焼失した後に建てられたもので，木造骨組の表面に石を貼り耐火に備えた構造になる。意匠は全体的にはロマネスク風だが，バラ窓等の細部にはゴシック風の意匠もみられる。市街地のランドマーク的存在として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000720"},{"id":"00015272","register_sub_id":"101","register_pk":"532396","name":"本行寺旧納骨堂","kana":"ほんぎょうじきゅうのうこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"北海道","address":"北海道釧路市弥生二丁目31他","lat":42.97300833,"lng":144.37698889,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積88㎡、渡廊下付","structure_material":"木造平屋建","registered":null,"register_no":"01 - 0173","desc":"本堂の北に接続する納骨堂。西面して建つ入母屋造妻入鉄板葺で正面に入母屋造庇を付す。内部は一室の板敷で南西に納骨棚を設ける。側廻りは櫛形欄間付の上下窓を並べ、外壁モルタル塗仕上、腰は目地を切り石造風。重厚な外観が本堂とともに境内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015272"},{"id":"00015271","register_sub_id":"101","register_pk":"532395","name":"本行寺本堂","kana":"ほんぎょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道釧路市弥生二丁目31他","lat":42.97285,"lng":144.37685556,"geo_status":"db","era":"大正14年／平成4年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋一部2階建一部地階付、銅板葺、建築面積841㎡","structure_material":"木造平屋一部2階建一部地階付","registered":"2025.03.13(令和7.03.13)","register_no":"01 - 0172","desc":"市街地南西の高台にある浄土真宗寺院の本堂。境内中央に西面して建つ木造二階建入母屋造で正面に千鳥破風を飾り入母屋造玄関を付す。小屋組はトラス。和風を基調とし、外壁は目地を切って石造風。外部木鼻彫刻など精緻な左官技術を示す良質な近代和風の本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015271"},{"id":"00010541","register_sub_id":"101","register_pk":"201115","name":"カトリック十和田教会","kana":"かとりっくとわだきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"青森県","address":"青森県十和田市稲生町162","lat":40.6174021,"lng":141.2128569,"geo_status":"db","era":"昭和7年／昭和39年移築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積165㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"02－0100","desc":"角地に建つ木造教会。正面の切妻屋根に鐘塔を戴き、切妻の玄関を張出し、外壁下見板張にアーチ窓を配する。内部は三廊式で側廊上部を回廊とする。身廊両側に柱頭飾を載せた円柱を並べ、連続アーチを架ける。教会建築を多く手掛けたヒンデルによる清楚な教会。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010541"},{"id":"00016337","register_sub_id":"101","register_pk":"536404","name":"最勝院庚申堂","kana":"さいしょういんこうしんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.59632222,"lng":140.46923889,"geo_status":"db","era":"江戸後期／昭和前期改修、同39年頃移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積3.8㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0110","desc":"聖徳太子堂の南に西面して建つ庚申堂。一間社見世棚造の形式で屋根鉄板葺。井桁に組んだ土台上に円柱を立てて頭貫で固め、三斗を組み、軒は板軒、妻飾は虹梁大瓶束笈形付とする。全体に弁柄塗を施しつつ、海老虹梁、肘木、蟇股の彫刻や彩色など装飾華やか。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016337"},{"id":"00016339","register_sub_id":"101","register_pk":"536406","name":"最勝院五智如来堂","kana":"さいしょういんごちにょらいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.59643333,"lng":140.46911667,"geo_status":"db","era":"弘化3年(1846)／昭和7年改修、同39年頃移築、平成28年改修","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0112","desc":"護摩堂の北東に西面して建つ五智如来堂。正面三間、側面三間、切妻造鉄板葺で一間向拝を付す。正面中央間は引分戸、脇間は格子戸、壁は白漆喰塗で腰は竪板張。内部は一室の板敷で背面側を仏壇とする。向拝中備に龍の彫刻を飾り、境内の歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016339"},{"id":"00016334","register_sub_id":"101","register_pk":"536401","name":"最勝院護摩堂","kana":"さいしょういんごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.59634167,"lng":140.46895556,"geo_status":"db","era":"文化14年（1817）／江戸末期改修、昭和39年頃移築、平成27年改修","year":1817,"year_source":"db","year_min":1817,"year_max":1817,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0107","desc":"弘前城跡の南東に位置する真言宗寺院の護摩堂。境内中央に北面して建つ宝形造銅板葺で、一間向拝を付し、頂部に宝珠を飾る。組物は舟肘木で軒は一軒疎垂木。内部は内外陣からなり、背面側の仏壇中央を須弥壇とする。全体に装飾少なく質実なつくりの護摩堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016334"},{"id":"00016335","register_sub_id":"101","register_pk":"536402","name":"最勝院聖徳太子堂","kana":"さいしょういんしょうとくたいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.59634444,"lng":140.46922778,"geo_status":"db","era":"江戸後期／大正2年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積2.0㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0108","desc":"護摩堂の東に西面して建つ太子堂。一間四方の宝形造銅板葺で、頂部に宝珠を飾り、四周に切目縁を廻らす。土台建ちの円柱に三斗を組み、軒は二軒扇垂木、中備は菊花の彫刻付蟇股とし、正面に桟唐戸を開く。組物などに彩色を施し、全体に装飾華やかな小堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016335"},{"id":"00016341","register_sub_id":"101","register_pk":"536408","name":"最勝院鐘楼","kana":"さいしょういんしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.59674167,"lng":140.46877222,"geo_status":"db","era":"昭和31年","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造、銅板葺、面積9.5㎡、周囲石柱付","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0114","desc":"境内中央に位置する鐘楼。基壇上に建つ一間四方の入母屋造銅板葺で、四隅に几帳面取角柱を内転びに立て、各間隅寄りの控柱とともに地覆、腰貫、飛貫で固める。内部の上部は格天井を張り、格間に龍と草花を描き、中央に梵鐘を吊る。木太く堂々たる姿の鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016341"},{"id":"00016342","register_sub_id":"101","register_pk":"536409","name":"最勝院仁王門","kana":"さいしょういんにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.596275,"lng":140.46911667,"geo_status":"db","era":"文政10年（1827）／昭和2年改修、同39年頃移築","year":1827,"year_source":"db","year_min":1827,"year_max":1827,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0115","desc":"境内南東部に至る参道の仁王坂に東面して建つ八脚門。切妻造平入鉄板葺。柱は全て角柱で組物は舟肘木、妻飾上部は豕扠首で大斗上に拳鼻を付す特徴的なつくり。両脇間東側は床板敷で棹縁天井とし、かつて仁王像一対を安置。境内の正面構えをつくる仁王門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016342"},{"id":"00016340","register_sub_id":"101","register_pk":"536407","name":"最勝院如意輪観世音菩薩堂","kana":"さいしょういんにょいりんかんぜおんぼさつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.59662778,"lng":140.46925556,"geo_status":"db","era":"元治元年（1864）／平成18年改修","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積4.8㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0113","desc":"境内東側に西面して建つ六角堂。屋根銅板葺で頂部に露盤宝珠を飾る。土台上に六角柱を立て、地長押、内法長押を廻らし、絵様肘木で桁を受け、軒は一軒扇垂木。正面は桟唐戸を開いて縁を付し、木部は弁柄塗。大振りな持送で隅木を支え、軒廻り賑やかな小堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016340"},{"id":"00016336","register_sub_id":"101","register_pk":"536403","name":"最勝院文殊堂","kana":"さいしょういんもんじゅどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.59642222,"lng":140.46920833,"geo_status":"db","era":"江戸後期／昭和前期改修、同39年頃移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積3.7㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0109","desc":"聖徳太子堂の北に西面して建つ文殊堂。一間社見世棚造の形式で屋根鉄板葺とする。井桁に組んだ土台上に角柱を立て、地長押、内法長押を廻らし、頭貫で固め、組物は大斗で軒は板軒、妻飾は虹梁に棟束とする。全体に弁柄塗を施し、簡素ながら丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016336"},{"id":"00016338","register_sub_id":"101","register_pk":"536405","name":"最勝院薬師堂","kana":"さいしょういんやくしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.59634722,"lng":140.46912222,"geo_status":"db","era":"文政6年（1823）／昭和前期改修、同39年頃移築","year":1823,"year_source":"db","year_min":1823,"year_max":1823,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積2.5㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0111","desc":"聖徳太子堂の南西に西面して建つ薬師堂。一間社見世棚造の形式で、屋根鉄板葺。土台上に円柱を立てて、頭貫で固め、地長押、内法長押を廻らす。組物は用いず、軒は板軒とする。全体に簡素ながらも、文殊堂や庚申堂と並び建ち、境内の歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016338"},{"id":"00011617","register_sub_id":"101","register_pk":"210633","name":"法光寺承陽塔","kana":"ほうこうじじょうようとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"low","period":"昭和中","pref":"青森県","address":"青森県三戸郡南部町大字法光寺字法光寺20-6","lat":40.389355,"lng":141.3234,"geo_status":"db","era":"昭和24年","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造三重塔、銅板葺、建築面積55㎡","structure_material":"木造三重塔","registered":"2017.06.28(平成29.06.28)","register_no":"02-0102","desc":"道元の遺骨を奉安するための三重塔で、総高三三メートル。初層は全て丸柱、上部は内部のみ角柱とし、心柱も角柱を用いる。組物は三手先で間に彫刻を飾り、軒は三層とも二軒繁垂木。戦後に建てられた木造三重塔の中でも最大級の規模を有する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011617"},{"id":"00001468","register_sub_id":"101","register_pk":"102458","name":"盛田牧場馬頭観音堂奥殿","kana":"もりたぼくじょうばとうかんのんどうおくでん","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"青森県","address":"青森県上北郡七戸町字膝森14-1","lat":40.70998866,"lng":141.17129604,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、銅板葺、建築面積8.2㎡","structure_material":"木造平屋建","registered":"2000.02.15(平成12.02.15)","register_no":"02 － 0009","desc":"もと盛田家の稲荷大明神であったが，戦後に現地に移築し，馬頭観音を祀った。屋敷神を祀る社としては規模の大きな正式の１間社流造で，中備蟇股や虹梁等の絵様が流麗で，装飾彫物も質が高い。建築年代は盛田家が農場経営を開始した明治初期頃と推定される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001468"},{"id":"00001470","register_sub_id":"101","register_pk":"102460","name":"盛田牧場馬頭観音堂鳥居","kana":"もりたぼくじょうばとうかんのんどうとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"青森県","address":"青森県上北郡七戸町字膝森14-1","lat":40.71025196,"lng":141.17123035,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、幅2.7m","structure_material":"木造","registered":"2000.02.15(平成12.02.15)","register_no":"02 － 0011","desc":"馬頭観音堂は牧場内の木立の中にあり，その参道南側に鳥居が建っている。丸太状の部材を用い，親柱を掘立で建てた素朴な形式で，額束をもつ点で鹿島鳥居と異なる。奥殿・拝殿とともに，牧場景観の構成要素として欠かせない存在になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001470"},{"id":"00001469","register_sub_id":"101","register_pk":"102459","name":"盛田牧場馬頭観音堂拝殿","kana":"もりたぼくじょうばとうかんのんどうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"青森県","address":"青森県上北郡七戸町字膝森14-1","lat":40.71009197,"lng":141.17140271,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2000.02.15(平成12.02.15)","register_no":"02 － 0010","desc":"入母屋造・鉄板葺で正面向拝付の３間堂で，盛田家の稲荷大明神を移築するまでは，馬頭観音を祀っていた。装飾細部の少ない簡素な建物で，建築年代は堂の扁額の年記より，盛田牧場として各種の施設を整えていった明治４０年頃と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001469"},{"id":"00015113","register_sub_id":"101","register_pk":"530537","name":"愛宕神社本殿（旧愛宕山大権現堂）","kana":"あたごじんじゃほんでん（きゅうあたごさんだいごんげんどう）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"岩手県","address":"岩手県奥州市江刺愛宕字西下川原197","lat":39.17558889,"lng":141.15461389,"geo_status":"db","era":"正徳4年(1714)／文久2年（1862）・昭和32年改修","year":1714,"year_source":"db","year_min":1714,"year_max":1714,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"03 - 0125","desc":"北上川東岸、かつて下川原御蔵があった集落の鎮守。境内西側の基壇上に東面して建つ宝形造三間堂で正面一間向拝付。三斗を組み、中備は蟇股で十二支彫刻を飾り、軒はせがい造。内部一室で西辺中央に須弥壇を設ける。小壁や組物などに塗装彩色を一部残し貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015113"},{"id":"00011032","register_sub_id":"101","register_pk":"205139","name":"上和野馬頭観世音旧堂","kana":"かみわのばとうかんぜおんきゅうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"岩手県","address":"岩手県岩手郡雫石町上野下沢田105","lat":39.706621,"lng":140.924808,"geo_status":"db","era":"江戸中期／明治14改修、大正3移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、鉄板葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"03 - 0085","desc":"北面して建つ三間堂で、正面に一間向拝を設ける。前身本堂と伝わり、現在は絵馬堂として用いられる。痕跡から、当初は奥に三間通しの仏壇が設けられていたとみられる。名馬の産地として知られた当地における信仰の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011032"},{"id":"00011031","register_sub_id":"101","register_pk":"205138","name":"上和野馬頭観世音本堂","kana":"かみわのばとうかんぜおんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県岩手郡雫石町上野下沢田105","lat":39.706761,"lng":140.924657,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"03 - 0084","desc":"袖山山麓に東向きに境内を開く。本堂は東面して建つ三間堂で、正面に一間向拝を設ける。正側面に高欄付の縁を廻らし、脇障子を備える。柱上を尾垂木付二手先組物で華やかに飾り、内部板支輪の地紋彫や、向拝周りの立体的な彫刻などに見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011031"},{"id":"00015114","register_sub_id":"101","register_pk":"530538","name":"旧盛岡天主堂","kana":"きゅうもりおかてんしゅどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"岩手県","address":"岩手県盛岡市厨川五丁目54-1","lat":39.74928611,"lng":141.12535278,"geo_status":"db","era":"大正元年／昭和前期改修、同42年増築、同53年移築","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、鉄板葺一部スレート葺、建築面積226㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"03 - 0126","desc":"盛岡大学附属高等学校敷地内に建つ。切妻造鉄板葺で正面にスレート葺鐘楼を戴く。三廊式で、正面に玄関、背面に半円形平面の祭壇を付す。身廊は柱頭飾付き円柱を並べてアーチを架けヴォールト天井を張る。ロマネスクを基調とした繊細な意匠の木造天主堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015114"},{"id":"00005819","register_sub_id":"101","register_pk":"106806","name":"日本基督教団一関教会","kana":"にほんきりすときょうだんいちのせききょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県一関市田村町2-14","lat":38.928829,"lng":141.131943,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積171㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"03 － 0064","desc":"通りに面して建つ，建築面積１７１㎡，木造平屋建，鉄板葺。聖堂正面右側に尖塔が建つ。小屋組はハンマービームやタイバー等で構成される。外壁は下見板張で２連尖頭アーチ窓を配し，聖堂正面の窓や玄関上部は三葉形アーチ意匠で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005819"},{"id":"00012682","register_sub_id":"101","register_pk":"367586","name":"青葉神社旧愛姫社鞘堂","kana":"あおばじんじゃきゅうめごひめしゃさやどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区青葉町173他","lat":38.28242583,"lng":140.8674,"geo_status":"db","era":"昭和6年／昭和中期移築・改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"04 － 164","desc":"拝殿の前方に南面して建つ。桁行二間梁間一間、入母屋造銅板葺妻入で、正面に桟唐戸、側面に連子窓を設ける。内部は畳敷で格天井を張る。組物は大斗肘木、妻飾は豕叉首、軒は一軒疎垂木。小規模ながら、拳鼻や肘木に本殿と共通の絵様をもつ上質な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012682"},{"id":"00012681","register_sub_id":"101","register_pk":"367585","name":"青葉神社神饌所及び伝供廊","kana":"あおばじんじゃしんせんじょおよびでんくろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区青葉町173他","lat":38.28242583,"lng":140.8674,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"04 － 163","desc":"拝殿の北西方に建つ。神饌所は桁行三間梁間三間、入母屋造銅板葺で、東面南端に設けた切妻造銅板葺の伝供廊で拝殿と接続する。内部は南に廊下、北に板敷の一室を配し、組物は舟肘木、軒は一軒疎垂木とする。拝殿と融和して近代的な社頭景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012681"},{"id":"00012679","register_sub_id":"101","register_pk":"367583","name":"青葉神社透塀","kana":"あおばじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区青葉町173他","lat":38.28242583,"lng":140.8674,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造、銅板葺、総延長87m、潜戸付","structure_material":"木造","registered":"2019.03.29(平成31.03.29)","register_no":"04 － 161","desc":"本殿の四周を結界する木造銅板葺の透塀。基壇は切石積、腰は井桁と襷桟付の板張、腰上は木連格子とし、両側面の前方に桟唐戸の潜門を設ける。屋根は肘木付の腕木で軒桁を受け、一軒疎垂木とする。良材を用いた精緻なつくりで、本殿の周辺を格調高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012679"},{"id":"00012678","register_sub_id":"101","register_pk":"367582","name":"青葉神社中門及び祝詞舎","kana":"あおばじんじゃちゅうもんおよびのりとしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区青葉町173他","lat":38.28242583,"lng":140.8674,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"中門 木造、銅板葺、間口3.6m 祝詞舎 木造、銅板葺、面積8.8㎡","structure_material":"中門 木造","registered":"2019.03.29(平成31.03.29)","register_no":"04 － 160","desc":"本殿正面の透塀に開く中門と、その背面に棟を直交して接続する祝詞舎。中門は切妻造銅板葺の四脚門で、組物は大斗肘木、中備は蟇股、軒は一軒。祝詞舎は切妻造銅板葺の吹放ち形式で、豕叉首上の肘木で棟木を受ける。本殿と共通の意匠をもつ上質な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012678"},{"id":"00012680","register_sub_id":"101","register_pk":"367584","name":"青葉神社拝殿","kana":"あおばじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区青葉町173他","lat":38.28242583,"lng":140.8674,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積101㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"04 － 162","desc":"本殿正面に南面して建つ。桁行五間梁間三間、入母屋造銅板葺、向拝一間付で四周に縁を廻す。組物は大斗肘木、中備は正背面の中央間のみに配する。軒は一軒。内部は畳敷で格天井を張る。整然とした参道の突当りにある近代的な社頭景観の中核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012680"},{"id":"00012677","register_sub_id":"101","register_pk":"367581","name":"青葉神社本殿","kana":"あおばじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区青葉町173他","lat":38.28242583,"lng":140.8674,"geo_status":"db","era":"大正13年","year":1924,"year_source":"converted","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"04 － 159","desc":"仙台旧城下北端の伊達政宗を祀る神社。本殿は前室付三間社流造銅板葺、向拝一間付で四周に縁を廻す。組物は平三斗で庇を大斗肘木とする。木鼻は幾何学的な意匠だが庇中央間と向拝の蟇股は中世風とするなど、伝統形式や意匠を巧みに構成し直した近代神社本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012677"},{"id":"00008610","register_sub_id":"101","register_pk":"149331","name":"大崎八幡宮旧宮司宿舎","kana":"おおさきはちまんぐうきゅうぐうじしゅくしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区八幡4-170","lat":38.27143735,"lng":140.84448562,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"04 － 0086","desc":"社務所の南に渡り廊下を介して繋がる。入母屋造東西棟の主棟北面に、寄棟屋根を付設。桟瓦葺。田字型に4室を配し、北面にトコを備えた社務室を突出する。社務所玄関と同様の緩やかな起りをもつ主棟妻を正面に見せ、社務所と外観の調和が図られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008610"},{"id":"00008609","register_sub_id":"101","register_pk":"149330","name":"大崎八幡宮社務所","kana":"おおさきはちまんぐうしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区八幡4-170","lat":38.27158003,"lng":140.84452527,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積171㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"04 － 0085","desc":"参道の西側に東面して建つ。主棟は入母屋造、西に寄棟屋根、東に入母屋造の玄関を付ける。桟瓦葺。トコとトコ脇を設ける主室と次の間を南北に配し、主室西側に貴賓室を付設。貴賓室にはトコと違棚、付書院を備える。玄関の屋根は優美な起りをもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008609"},{"id":"00008611","register_sub_id":"101","register_pk":"149332","name":"大崎八幡宮神馬舎","kana":"おおさきはちまんぐうしんめしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区八幡4-170","lat":38.2716811,"lng":140.84516374,"geo_status":"db","era":"大正後期／平成22年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"04 － 0087","desc":"社務所の東方、参道を挟んだ位置に建つ。南北棟の入母屋造桟瓦葺で、西面は縋破風を付け、葺き降ろす。北寄りに床上部、南は東に厩2室を設け、西に土間を通し、物置を突出する。厩は土間に厚板を敷き詰め、内法下を竪板張とするなど、伝統的な仕様を受け継ぐ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008611"},{"id":"00014228","register_sub_id":"101","register_pk":"509618","name":"大高森薬師堂","kana":"おおたかもりやくしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県東松島市宮戸字瀬戸浜23-1","lat":38.33997778,"lng":141.15129167,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"04 - 0214","desc":"特別名勝松島の宮戸島に所在。公園整備の一環で建設された薬師堂。正面三間側背面二間宝形造桟瓦葺。丸柱を長押で固め組物は舟肘木で軒は一軒疎垂木。正面に板唐戸、側面に連子窓を建てる。向拝を持たず、瓦当に重弁蓮華文を施す等、復古的な様相を示す仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014228"},{"id":"00013476","register_sub_id":"101","register_pk":"504844","name":"大嶽山興福寺書院及び庫裏","kana":"おおだけさんこうふくじしょいんおよびくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県登米市南方町本郷大嶽18","lat":38.65590556,"lng":141.18680556,"geo_status":"db","era":"明治中期／大正11年・昭和56年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建一部2階建、銅板及び鉄板葺、建築面積312㎡","structure_material":"木造平屋建一部2階建","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0181","desc":"旧南方町にある天台宗寺院。境内中央に南面して建ち、西は寄棟造の書院、東は正面を入母屋造とした庫裏とし、書院正面東端に唐破風造屋根を付す。書院は前後二列の室配置を基本に素朴に造るが、北西座敷の床構えに色ガラスを用いる等先駆的な試みも見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013476"},{"id":"00016476","register_sub_id":"101","register_pk":"574838","name":"久須師神社拝殿（旧薬師堂）","kana":"くすしじんじゃはいでん（きゅうやくしどう）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"宮城県","address":"宮城県石巻市尾崎字宮下52","lat":38.4278775,"lng":141.30606389,"geo_status":"db","era":"文久2年（1862）／明治11年・同29年・昭和34年改修","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"04 - 0245","desc":"長面浦北岸にある神社の拝殿。西面して建つ桁行三間梁間三間、入母屋造スレート葺で正面に一間向拝を付し、三方に擬宝珠高欄付縁を廻らす。組物は禅宗様の尾垂木付三手先で軒は二軒扇垂木、向拝柱の地紋彫など要所を彫刻で飾る。スレート葺屋根の希少な拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016476"},{"id":"00016343","register_sub_id":"101","register_pk":"536410","name":"西光寺大滝不動堂","kana":"さいこうじおおたきふどうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"宮城県","address":"宮城県仙台市太白区秋保町馬場字大滝11","lat":38.27412778,"lng":140.603925,"geo_status":"db","era":"文政8年（1825）頃／昭和29年改修","year":1825,"year_source":"db","year_min":1825,"year_max":1825,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積76㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"04 - 0228","desc":"秋保大滝の南岸に建つ真言宗寺院西光寺の不動堂。宝形造銅板葺、一間向拝付の大型三間堂。軒は三軒。組物は出組で板支輪や小壁、蟇股、向拝廻りなどを華麗な彫刻で飾り、外陣天井格間に草花、内陣天井に双龍の墨画を描く。地域の信仰を集める装飾豊富な仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016343"},{"id":"00013921","register_sub_id":"101","register_pk":"508181","name":"孝子堂","kana":"せんねんじこうしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県白石市大鷹沢三沢字熊野堂42","lat":37.99295833,"lng":140.638325,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.8㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0209","desc":"歌舞伎の仇討ち演目である白石噺ゆかりの小堂で、話の発端となる水田を見下ろす丘に所在する。方一間宝形造銅板葺向拝付で、虹梁や組物で飾り、四周切目縁で全体に朱漆塗とする。内部は一室で仇を討ち果たした姉妹の像を祀り、文人や花柳界の信仰を集めた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013921"},{"id":"00014708","register_sub_id":"101","register_pk":"518966","name":"津島神社拝殿","kana":"つしまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県登米市迫町佐沼字西佐沼141","lat":38.68434167,"lng":141.19684722,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"04 - 0218","desc":"本殿の北に建つ入母屋造平入銅板葺の東西棟で北面の三間向拝に軒唐破風を付す。三方に縁を付して脇障子を建て、組物は出組で軒支輪を備え、軒は二軒繁垂木とする。内部は一室の畳敷で、格天井を張る。妻飾や海老虹梁など彫刻で華やかに飾り時代相を示す拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014708"},{"id":"00014707","register_sub_id":"101","register_pk":"518965","name":"津島神社本殿","kana":"つしまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県登米市迫町佐沼字西佐沼141","lat":38.6842,"lng":141.19685,"geo_status":"db","era":"大正8年","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"04 - 0217","desc":"仙台藩の要害、佐沼にある神社。境内南寄りに北面する本殿は一間社流造銅板葺で、三方に縁を廻らし、脇障子を建てる。組物は出組とし軒は二軒繁垂木。妻飾は虹梁大瓶束で笈形を付し、頂部には花肘木を重ねて棟木を支える。全体に彫刻が濃密で華やかな本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014707"},{"id":"00014709","register_sub_id":"101","register_pk":"518967","name":"津島神社神輿殿","kana":"つしまじんじゃみこしでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県登米市迫町佐沼字西佐沼141","lat":38.68450833,"lng":141.19676667,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積9.7㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"04 - 0219","desc":"拝殿北西に建つ桁行３間、梁間２間、平屋建入母屋造妻入銅板葺の東西棟。組物は出三斗、軒は一軒繁垂木。東の戸口に両開の格子戸を開く。内部は一室の土間で格天井を張り、中央に神輿を置く。簡素ながらも丁寧なつくりで境内の歴史的景観を形成する神輿殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014709"},{"id":"00012088","register_sub_id":"101","register_pk":"352887","name":"定義如来西方寺御守授所","kana":"ていぎにょらいさいほうじおまもりじゅじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区大倉字上下1","lat":38.363709,"lng":140.668371,"geo_status":"db","era":"昭和2年／昭和51年曳家、昭和32年・平成20年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.1㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"04-146","desc":"御廟貞能堂の前方、参道南側に建つ。桁行二・九メートル、梁間二・一メートルの小ぶりな建物であるが、屋根を入母屋造銅板葺とするなど本格的な造り。四面に腰長押を廻らし、足元は下見板張、東と北面は全面ガラス戸とし、そのほかは竪板壁に窓や入口を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012088"},{"id":"00012087","register_sub_id":"101","register_pk":"352886","name":"定義如来西方寺御廟貞能堂","kana":"ていぎにょらいさいほうじごびょうさだよしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区大倉字上下1","lat":38.363831,"lng":140.668266,"geo_status":"db","era":"昭和2年／昭和32年・同43年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積165㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"04-145","desc":"平貞能の墳墓上に建てられた小堂を起源とし、前身堂の部材を一部再用した。六角堂の背後に方形の裏堂が附属する構成で、屋根は銅板葺の六注造宝塔屋根付。周囲に裳階状の廻廊が廻り、正面に向唐破風付向拝を付す。外部を中心に彫刻で飾る特色ある堂宇である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012087"},{"id":"00012091","register_sub_id":"101","register_pk":"352890","name":"定義如来西方寺山門","kana":"ていぎにょらいさいほうじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区大倉字上下1","lat":38.363601,"lng":140.668742,"geo_status":"db","era":"昭和7年／昭和32年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、銅板葺、建築面積25㎡、左右袖塀付","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"04-149","desc":"西方寺境内の旧中心地の入口を画す。三間一戸の二重門で屋根は入母屋造銅板葺とし、上層正面側中央に軒唐破風を付す。虹梁より上部に多量の彫刻を入れ、組物は出組、軒は上層下層とも二軒繁垂木とする。気仙大工の手による、装飾豊かな山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012091"},{"id":"00012089","register_sub_id":"101","register_pk":"352888","name":"定義如来西方寺鐘楼堂","kana":"ていぎにょらいさいほうじしょうろうどう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区大倉字上下1","lat":38.363755,"lng":140.668582,"geo_status":"db","era":"昭和7年／昭和32年・同60年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造、銅板葺、面積11㎡","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"04-147","desc":"山門奥、参道の北側に建つ木造平屋建、入母屋造銅板葺の鐘楼堂。四隅の円柱を腰貫で固め、内法貫・頭貫の位置に虹梁を重ねて木鼻を出し、台輪を置く。虹梁間には菱格子欄間を入れ、出組、中備蟇股、二軒繁垂木とする。天井は格天井である。装飾豊かな鐘楼堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012089"},{"id":"00012090","register_sub_id":"101","register_pk":"352889","name":"定義如来西方寺手水舎","kana":"ていぎにょらいさいほうじてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区大倉字上下1","lat":38.363642,"lng":140.668595,"geo_status":"db","era":"昭和8年頃／昭和32年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造、銅板葺、面積2.8㎡","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"04-148","desc":"山門奥にあって参道の南側に建つ切妻造銅板葺の手水舎。四隅に角柱を立て、頭貫の位置に虹梁を入れ、天井は格天井とする。組物は三斗組、中備蟇股、軒は二軒繁垂木である。小ぶりながら装飾豊かで、本格的な意匠を備える境内建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012090"},{"id":"00011035","register_sub_id":"101","register_pk":"205142","name":"當信寺山門","kana":"とうしんじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県白石市字本町62","lat":38.0003,"lng":140.622982,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積13㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"04 - 0122","desc":"白石城二之丸大手二之門の部材を用いて建てられたと伝わる。三間一戸門で、上部にはもと櫓部とみられる切妻造瓦葺の鐘楼を載せ、その中央には宝珠形の枠を付けた大きな開口を設ける。幕末の動乱を経て、近世から近代へ移り変わる旧城下の歴史をしのばせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011035"},{"id":"00011034","register_sub_id":"101","register_pk":"205141","name":"當信寺本堂","kana":"とうしんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"宮城県","address":"宮城県白石市字本町62","lat":38.000241,"lng":140.623301,"geo_status":"db","era":"天保2","year":1831,"year_source":"db","year_min":1831,"year_max":1831,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"04 - 0121","desc":"白石城下の南東に境内を構える。正面一間通りの広縁と、その奥の外陣、そして内陣、脇間からなる浄土宗寺院本堂の特徴的平面である。内陣組物は支輪付出組とし、鏡天井を張る。正面には一間向拝を設け、手挟に籠彫の彫刻を嵌めるなど、要所を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011034"},{"id":"00014997","register_sub_id":"101","register_pk":"529275","name":"日本基督教団岩沼教会","kana":"にほんきりすと きょうだんいわぬまきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県岩沼市桜二丁目37-2","lat":38.10566111,"lng":140.86855556,"geo_status":"db","era":"昭和5年／平成4年・同24年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"石造平屋一部3階建、銅板葺、建築面積120㎡","structure_material":"石造平屋一部3階建","registered":"2024.08.15(令和6.08.15)","register_no":"04 - 0221","desc":"岩沼市街地に位置する教会。石造平屋建切妻造銅板葺の礼拝堂に宝形造塔屋を付属。外観は石積を現し尖塔アーチ窓を並べる。内部は玄関から東へ礼拝室、講壇を配し、小屋はハンマービームとタイバーを用い天井を折上げる。石造の重厚な外観が地域景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014997"},{"id":"00004308","register_sub_id":"101","register_pk":"105298","name":"新波神社拝殿","kana":"あらわじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県秋田市雄和新波字樋口16","lat":39.526939,"lng":140.23093797,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"05 － 0111","desc":"桁行３間梁行２間規模，入母屋造，鉄板葺，平入の拝殿で，正面に１間の軒唐破風付き向拝を設け，３面に刎高欄付縁を廻らす。柱は円柱，組物は二手先で尾垂木・支輪を備える。軒は二軒繁垂木。各部の彫物に見所がある。棟梁は松本銀蔵らと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004308"},{"id":"00015118","register_sub_id":"101","register_pk":"530542","name":"旧観音寺鐘楼","kana":"きゅうかんのんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市本町168-1","lat":39.31901389,"lng":140.56661111,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、鉄板葺、面積23㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"05 - 0246","desc":"横手川北岸に張出す高台上に建つ、旧真言宗寺院の袴腰付鐘楼。方一間、入母屋造鉄板菱葺で、柱間に虹梁形頭貫を架けて三斗を組み、軒は二軒繁垂木とする。四方を吹放ち、欄干を廻し、上部中央に梵鐘を吊る。景勝地の蛇の崎に建ち、地域のランドマーク的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015118"},{"id":"00003944","register_sub_id":"101","register_pk":"104934","name":"金嶺山龍源寺本堂","kana":"きんれいざんりゅうげんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県由利本荘市矢島町城内字田屋の下26","lat":39.23160793,"lng":140.13089702,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、茅葺、建築面積441㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"05 － 0096","desc":"桁行２４ｍ梁間１６ｍの大規模な木造寺院建築で，左側に位牌堂へ通ずる廊下を設け，正面東寄りに入母屋造，軒唐破風とした向拝を付ける。棟札から棟梁「佐々木光信」が判明。雄大な茅葺屋根に特色があり，重厚な佇まいが，周囲の杉木立によく溶け込んでいる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003944"},{"id":"00015119","register_sub_id":"101","register_pk":"530543","name":"正平寺経蔵","kana":"しょうへいじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県横手市田中町58-2","lat":39.31225,"lng":140.56574167,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積30㎡、輪蔵付","structure_material":"土蔵造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"05 - 0247","desc":"横手城跡南西の旧外町に位置する曹洞宗寺院の経蔵。境内南東に建つ土蔵造切妻造妻入鉄板葺で、北面に向唐破風向拝を付す。外壁モルタル洗出仕上で目地を切り石造風。内部は一室の土間で中央に江戸後期の八角輪蔵を納める。大振りな向拝が華やかな外観の経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015119"},{"id":"00015120","register_sub_id":"101","register_pk":"530544","name":"正平寺山門","kana":"しょうへいじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市田中町58-2","lat":39.31258889,"lng":140.565875,"geo_status":"db","era":"明治37年／昭和42年改修","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造、鉄板葺、間口6.9m、袖塀付","structure_material":"木造","registered":"2024.12.03(令和6.12.03)","register_no":"05 - 0248","desc":"境内北東隅、羽州街道に東面して建つ、三間一戸の薬医門で両脇に鉄板葺袖塀を付す。主柱、控柱の冠木上に渡した梁先端に平三斗を配して二軒を支持。妻飾は虹梁大瓶束風で梁側面まで彫刻で飾り、装飾豊富で賑やかな外観。赤門と地域で呼び親しむ大規模な山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015120"},{"id":"00004692","register_sub_id":"101","register_pk":"105682","name":"神明社稲荷鳥居","kana":"しんめいしゃいなりとりい","category":"宗教","subcategory":"建築物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"秋田県","address":"秋田県由利本荘市吉沢字上林42","lat":39.26548252,"lng":140.11374948,"geo_status":"db","era":"文化7","year":1810,"year_source":"db","year_min":1810,"year_max":1810,"year_label":null,"structure":"石造、高さ4.1m、幅3.0m","structure_material":"石造","registered":"2005.07.12(平成17.07.12)","register_no":"05 － 0121","desc":"参道入口から石段を上がった位置に建つ石製鳥居。反りのある笠木と島木，柱上に台輪をもつ稲荷鳥居の形式である。全高約４ｍ，柱間約３ｍで，柱高さ３．４ｍに対して２５㎝の内転びを持つ。厚みのある台輪，幅の広い台形の額束に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004692"},{"id":"00004107","register_sub_id":"101","register_pk":"105097","name":"神明社宮殿","kana":"しんめいしゃくうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県由利本荘市吉沢字上林42","lat":39.26470683,"lng":140.1152146,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、板葺、建築面積2㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"05 － 0109","desc":"本殿内に安置された金箔塗，装飾豊かな宮殿で，寄棟屋根に千鳥破風付きの切妻屋根を載せた屋根の造形は特異。千鳥破風の懸魚には当地を治めた六郷氏の六郷亀甲を用いる。棟札から「大工棟梁尾留川宇左エ門 塗師棟梁小松権之丞 彫師小川松四郎」が判明する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004107"},{"id":"00004690","register_sub_id":"101","register_pk":"105680","name":"神明社境内社合殿","kana":"しんめいしゃけいだいしゃあいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県由利本荘市吉沢字上林42","lat":39.26462977,"lng":140.11513394,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、鉄板葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"05 － 0119","desc":"桁行４間半，梁間３間の木造平屋建，切妻造の妻入で，屋根を鉄板葺とする。正面柱上に舟肘木を飾り，妻に梁を重ねる。奥から４尺半に円柱を立て，出組，実肘木，蟇股を飾り，一段高く床を張って内陣とする。外陣天井の一部には嘉永５年銘の龍像墨絵がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004690"},{"id":"00004108","register_sub_id":"101","register_pk":"105098","name":"神明社拝幣殿","kana":"しんめいしゃはいへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"秋田県","address":"秋田県由利本荘市吉沢字上林42","lat":39.26477818,"lng":140.11505901,"geo_status":"db","era":"慶応3／大正4増築","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積158㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"05 － 0110","desc":"桁行３間梁間３間の拝殿と桁行３間梁間２間の幣殿から成る。棟をＴ字形にした社殿で，千鳥破風と軒唐破風付き向拝とによる正面構えをとり，向拝柱と拝殿側柱に架けられた繋虹梁の上には力士像一対を置くなど，装飾性豊かな彫物で正面を飾っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004108"},{"id":"00004106","register_sub_id":"101","register_pk":"105096","name":"神明社本殿","kana":"しんめいしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県由利本荘市吉沢字上林42","lat":39.26471242,"lng":140.11519139,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"05 － 0108","desc":"子吉川左岸近くの高台に位置し，石積基壇上に建つ。神明造の社殿で，桁行３間（３．４３ｍ）梁間２間（３．４ｍ）規模，切妻造，銅板葺とし，棟に千木と勝男木を上げる。縁は隅を放射状とした切目縁で，縁の端近くまで妻壁から離して棟持柱を建てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004106"}];
